                let col = s.column;
                if (!col)
                    return;
                if (col === 'description_english')
                    col = 'english_description';
                if (col === 'image')
                    col = 'image_url';
                if (col === 'departments')
                    col = 'name';
                if (col === 'municipalities')
                    col = 'name';
                if (tableName === 'municipalities' && col === 'department_id')
                    col = 'departmentId';
                if (col === 'total_aves')
                    col = 'total_birds';
                if (col === 'tipos_aves')
                    col = 'bird_types';
                columns.push(col);
                validIndices.push(idx);
            });
            console.log(`Inserting ${table.values.length} rows into ${tableName}...`);
            let inserted = 0;
            for (const row of table.values) {
                const values = validIndices.map((idx) => {
                    let v = row[idx];
                    const colName = columns[validIndices.indexOf(idx)];
                    if (colName === 'sql_deleted')
                        return v === 1;
                    if (colName === 'last_modified') {
                        return new Date(v * 1000).toISOString();
                    }
                    if (typeof v === 'string' && v.trim() === '')
                        v = null;
                    if (v === null || v === undefined) {
                        if (colName === 'viewing_difficulty')
                            return 4;
                        if (colName === 'min_altitude' || colName === 'max_altitude')
                            return 0;
                        if (colName === 'size')
                            return 0;
                        if (colName === 'common_name' || colName === 'english_name' || colName === 'scientific_name')
                            return '-';
                        return null;
                    }
                    if (typeof v === 'string')
                        return v;
                    return v;
                });
                const placeholders = values.map((_, i) => `$${i + 1}`).join(', ');
                const quotedCols = columns.map(c => `"${c}"`).join(', ');
                const query = `INSERT INTO "${tableName}" (${quotedCols}) VALUES (${placeholders}) ON CONFLICT (id) DO NOTHING`;
                try {
                    await client.query(query, values);
                    inserted++;
                }
                catch (e) {
                    console.error(`Error in ${tableName} with query: ${query}`);
                    console.error(e.message);
                    break;
                }
            }
            console.log(`Successfully inserted ${inserted} rows into ${tableName}.`);
        }
