/**
 * @class RegisterPage
 * @description Maneja el registro de usuarios con validaciones dinámicas para proveedores.
 */
@Component({
  selector: 'app-register',
  templateUrl: './register.page.html',
  styleUrls: ['./register.page.scss'],
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink, PasswordMeterComponent, BrandHeaderComponent, AuthInputComponent, PasswordInputComponent, AuthCardHeaderComponent, IonContent, IonSelect, IonSelectOption, IonIcon, IonButton, IonModal],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RegisterPage {
  private readonly ui = inject(UiService);
  private readonly authStore = inject(AuthStore);
  private readonly router = inject(Router);
  private readonly modalCtrl = inject(ModalController);

  selectedRole = signal<string>('PAJARERO');
  showPassword = signal<boolean>(false);
  isFormSubmitted = signal<boolean>(false);

  // Form Signals
  firstName = signal<string>('');
  lastName = signal<string>('');
  username = signal<string>('');
  email = signal<string>('');
  password = signal<string>('');
  businessName = signal<string>('');
  rnt = signal<string>('');

  // Validaciones
  isFirstNameValid = computed(() => this.firstName().trim().length > 0);
  isLastNameValid = computed(() => this.lastName().trim().length > 0);
  isUsernameValid = computed(() => this.username().trim().length >= 4);
  isEmailValid = computed(() => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(this.email()));
  isPasswordValid = computed(() => this.password().length >= 8);
  
  isBusinessNameValid = computed(() => {
    const role = this.selectedRole();
    if (role === 'PROVEEDOR' || role === 'BOTH') return this.businessName().trim().length > 0;
    return true;
  });

  isRntValid = computed(() => {
    const role = this.selectedRole();
    if (role === 'PROVEEDOR' || role === 'BOTH') return this.rnt().trim().length > 0;
    return true;
  });

  isFormValid = computed(() => 
    this.isFirstNameValid() && 
    this.isLastNameValid() && 
    this.isUsernameValid() && 
    this.isEmailValid() && 
    this.isPasswordValid() && 
    this.isBusinessNameValid() && 
    this.isRntValid()
  );

  constructor() {
    addIcons({
      personOutline,
      mailOutline,
      lockClosedOutline,
      briefcaseOutline,
      documentTextOutline,
      eyeOutline,
      eyeOffOutline,
      arrowBackOutline,
    });
  }

  onRoleChange(event: CustomEvent): void {
    const role = event.detail.value;
    this.selectedRole.set(role);
    if (role === 'PAJARERO') {
      this.businessName.set('');
      this.rnt.set('');
    }
  }

  /** @method togglePassword */
  togglePassword(): void {
    this.showPassword.update((v) => !v);
  }

  /**
   * @method openTerms
   * @description Presenta la modal de Términos y Condiciones.
   */
  async openTerms(): Promise<void> {
    const modal = await this.modalCtrl.create({
      component: TermsModalComponent,
    });
    await modal.present();
  }

  async onRegister(): Promise<void> {
    this.isFormSubmitted.set(true);
    if (!this.isFormValid()) {
      this.ui.showToast('Completa los campos obligatorios', 'warning');
      return;
    }

    await this.ui.showLoading('Creando cuenta en AviTour...');

    try {
      const payload = {
        role: this.selectedRole() as UserRole,
        firstName: this.firstName(),
        lastName: this.lastName(),
        username: this.username(),
        email: this.email(),
        password: this.password(),
        businessName: this.businessName(),
        rnt: this.rnt()
      };
      
      await this.authStore.register(payload);

      await this.ui.dismissLoading();
      await this.ui.showToast('¡Cuenta creada con éxito!', 'success');
      
      // Reset form
      this.isFormSubmitted.set(false);
      this.firstName.set('');
      this.lastName.set('');
      this.username.set('');
      this.email.set('');
      this.password.set('');
      this.businessName.set('');
      this.rnt.set('');
      
      this.router.navigate(['/home'], { replaceUrl: true });
    } catch (err: unknown) {
      await this.ui.dismissLoading();
      const msg = (err as { error?: { message?: string } }).error?.message || 'Error al crear la cuenta.';
      await this.ui.showToast(msg, 'danger');
    }
  }
}

import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { AuthService } from '../services/auth.service';
import { DbHelperService } from '../services/db-helper.service';
import { User } from '../models/auth.models';

/**
 * Guard de Autenticación Funcional.
 * * Protege las rutas de la aplicación verificando la existencia de una sesión activa.
 * 1. Comprueba el estado en memoria (Signals).
 * 2. Si no hay memoria, intenta restaurar desde la persistencia local (SQLite).
 * 3. Bloquea el acceso y redirige al login si no se encuentra una sesión válida.
 * * @param route Información de la ruta activa.
 * @param state Estado del router.
 * @returns boolean | Promise<boolean> true si permite el acceso, false si lo deniega.
 */
export const authGuard: CanActivateFn = async (route, state) => {
  const authService = inject(AuthService);
  const db = inject(DbHelperService);
  const router = inject(Router);

  // 1. Revisar si ya está autenticado en el Signal (Memoria activa)
  // Esto optimiza la navegación entre rutas internas sin consultar la DB.
  if (authService.currentUser()) {
    return true;
  }

  // 2. Si no hay memoria, revisar si hay una sesión guardada en SQLite (Persistencia)
  try {
    const session = await db.getSession();

    if (session && session.token) {
      // Restauramos el usuario en el Signal del servicio (Regla 4: Tipado Estricto)
      const userData: User =
        typeof session.user_data === 'string'
          ? JSON.parse(session.user_data)
          : session.user_data;

      authService.currentUser.set(userData);
      return true;
    }
  } catch (error: unknown) {
    console.error('Error verificando sesión en la base de datos local:', error);
  }

  // 3. Si no hay sesión válida, redirigir al login
  // Reemplazamos la URL para no dejar rastro en el historial de navegación.
  router.navigate(['/auth/login'], { replaceUrl: true });
  return false;
};

import {
  HttpInterceptorFn,
  HttpRequest,
  HttpHandlerFn,
  HttpEvent,
} from '@angular/common/http';
import { inject } from '@angular/core';
import { DbHelperService } from '../services/db-helper.service';
import { AuthService } from '../services/auth.service';
import { from, Observable } from 'rxjs';
import { switchMap } from 'rxjs/operators';

/**
 * @function authInterceptor
 * @description Interceptor funcional que actúa como middleware para las peticiones HTTP salientes.
 * Su responsabilidad es adjuntar el token JWT (Bearer) a las cabeceras de autorización.
 * * Flujo de ejecución:
 * 1. Verifica la memoria RAM (AuthService) por velocidad.
 * 2. Si la RAM está vacía, consulta SQLite de forma asíncrona (DbHelperService).
 * 3. Si encuentra un token en SQLite, lo restaura a la RAM y clona la petición.
 * 4. Si no hay token en ninguna capa, deja pasar la petición original (ej. Login/Register).
 * * @param {HttpRequest<unknown>} req - La petición HTTP original inmutable.
 * @param {HttpHandlerFn} next - El despachador para continuar el ciclo de vida HTTP.
 * @returns {Observable<HttpEvent<unknown>>} Un observable con la petición modificada o intacta.
 */
export const authInterceptor: HttpInterceptorFn = (
  req: HttpRequest<unknown>,
  next: HttpHandlerFn
): Observable<HttpEvent<unknown>> => {
  const authService = inject(AuthService);
  const db = inject(DbHelperService);

  // PASO 1: Consulta ultrarrápida en memoria RAM
  const ramToken = authService.getToken();

  if (ramToken) {
    const authReq = req.clone({
      setHeaders: { Authorization: `Bearer ${ramToken}` },
    });
    return next(authReq);
  }

  // PASO 2: Si la memoria está vacía (ej. recargó la app/página), buscamos en SQLite
  return from(db.getSession()).pipe(
    switchMap((session) => {
      if (session && session.token) {
        // Restauramos el token en RAM para optimizar peticiones futuras
        authService.setToken(session.token);

        const authReq = req.clone({
          setHeaders: { Authorization: `Bearer ${session.token}` },
        });
        return next(authReq);
      }

      // PASO 3: Petición pública (sin sesión detectada)
      return next(req);
    })
  );
};

