import { inject, Injectable, signal } from '@angular/core';
import {
  ToastController,
  LoadingController,
  AlertController,
} from '@ionic/angular';
import { Haptics, ImpactStyle, NotificationType } from '@capacitor/haptics';

/**
 * Servicio global para la gestión de UI con estado reactivo y feedback háptico.
 */
@Injectable({
  providedIn: 'root',
})
export class UiService {
  private readonly toastCtrl = inject(ToastController);
  private readonly loadingCtrl = inject(LoadingController);
  private readonly alertCtrl = inject(AlertController);

  /** Signal para rastrear procesos de carga en toda la app */
  public isGlobalLoading = signal<boolean>(false);

  private activeLoading: HTMLIonLoadingElement | null = null;

  /**
   * Muestra Toast y añade vibración ligera de éxito/información.
   */
  async showToast(
    message: string,
    color: 'success' | 'danger' | 'warning' | 'primary' = 'primary',
    position: 'top' | 'bottom' | 'middle' = 'bottom'
  ): Promise<void> {
    if (color === 'success')
      await Haptics.notification({ type: NotificationType.Success });

    const toast = await this.toastCtrl.create({
      message,
      duration: 2500,
      color,
      position,
      buttons: [{ text: 'OK', role: 'cancel' }],
      cssClass: 'custom-toast',
    });
    await toast.present();
  }

  /**
   * Activa el spinner y el estado global de carga.
   */
  async showLoading(message: string = 'Cargando...'): Promise<void> {
    this.isGlobalLoading.set(true);
    if (this.activeLoading) await this.dismissLoading();

    this.activeLoading = await this.loadingCtrl.create({
      message,
      spinner: 'circles',
      backdropDismiss: false,
    });

    await this.activeLoading.present();
  }

  async dismissLoading(): Promise<void> {
    if (this.activeLoading) {
      await this.activeLoading.dismiss();
      this.activeLoading = null;
    }
    this.isGlobalLoading.set(false);
  }

  /**
   * Alerta crítica con vibración de advertencia.
   */
  async showAlert(header: string, message: string): Promise<void> {
    await Haptics.notification({ type: NotificationType.Warning });
    const alert = await this.alertCtrl.create({
      header,
      message,
      buttons: [
        { text: 'Aceptar', role: 'confirm', cssClass: 'alert-button-confirm' },
      ],
    });
    await alert.present();
  }

  /**
   * Alerta de confirmación con opciones Aceptar/Cancelar.
   * @returns Promesa booleana con el resultado de la confirmación
   */
  async showConfirm(header: string, message: string): Promise<boolean> {
    await Haptics.impact({ style: ImpactStyle.Light });
    
    return new Promise(async (resolve) => {
      const alert = await this.alertCtrl.create({
        header,
        message,
        buttons: [
          {
            text: 'Cancelar',
            role: 'cancel',
            cssClass: 'alert-button-cancel',
            handler: () => resolve(false),
          },
          {
            text: 'Eliminar',
            role: 'confirm',
            cssClass: 'alert-button-confirm',
            handler: () => resolve(true),
          },
        ],
      });
      await alert.present();
    });
  }
}

import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../environments/environment';
import { User, UserMedalDto } from '../models/auth.models';
import { DbHelperService } from './db-helper.service';

/**
 * @class UserService
 * @description Servicio de gestión de usuarios (Online-Only Pattern implementado).
 * @author Gemini (Frontend Agent)
 */
@Injectable({
  providedIn: 'root',
})
export class UserService {
  private readonly http = inject(HttpClient);
  private readonly db = inject(DbHelperService);
  private readonly API_URL = `${environment.apiUrl}/users`;
  private readonly UPLOAD_URL = `${environment.apiUrl}/uploads`;

  /**
   * @method getProfile
   * @description Obtiene el perfil del usuario directamente desde Postgres (Online-Only).
   * @returns {Promise<User>}
   */
  async getProfile(): Promise<User> {
    const remoteUser = await firstValueFrom(this.http.get<User>(`${this.API_URL}/me`));
    
    // Actualizamos la caché local (Token)
    const session = await this.db.getSession();
    if (session) {
      await this.db.saveSession(session.token, remoteUser);
    }
    
    return remoteUser;
  }

  /**
   * @method getProfileById
   * @description Consulta perfil público de terceros.
   * @param {string | number} id - UUID del usuario.
   * @returns {Promise<User>}
   */
  async getProfileById(id: string | number): Promise<User> {
    return firstValueFrom(this.http.get<User>(`${this.API_URL}/${id}`));
  }

  /**
   * Actualización directa en la API (Online-Only). Si falla (Offline), el interceptor lo bloqueará.
   * @param {Partial<User>} updateData - Payload de cambios.
   * @returns {Promise<User>}
   */
  async updateProfile(updateData: Partial<User>): Promise<User> {
    // 1. Ejecutar petición a Postgres directamente
    const remoteResponse = await firstValueFrom(
      this.http.patch<User>(`${this.API_URL}/me`, updateData)
    );

    // 2. Si es exitoso, actualizar la caché local
    const session = await this.db.getSession();
    if (session && remoteResponse) {
      await this.db.saveSession(session.token, remoteResponse);
    }
    
    return remoteResponse;
  }

  /**
   * @method uploadImage
   * @description Transfiere binarios de imagen al servidor segmentado.
   * @param {Blob} file - Archivo de imagen.
   * @param {string} type - Tipo de carga (avatar, cover, provider-cover).
   * @param {string} extension - Extensión del archivo original.
   * @returns {Promise<{ url: string }>}
   */
  async uploadImage(
    file: Blob,
    type: string,
    extension: string = 'jpg'
  ): Promise<{ url: string }> {
    const formData = new FormData();
    // R10: Inyección de nombre de archivo para validación de Multer
    formData.append('file', file, `upload_${Date.now()}.${extension}`);

    return firstValueFrom(
      this.http.post<{ url: string }>(`${this.UPLOAD_URL}/${type}`, formData)
    );
  }

  /**
   * @method updatePassword
   * @description Envía las nuevas credenciales al endpoint de seguridad.
   * @param {Object} data - Objeto con oldPassword y newPassword.
   */
  async updatePassword(data: { oldPassword?: string; newPassword?: string }): Promise<{ message: string }> {
    return firstValueFrom(
      this.http.patch<{ message: string }>(
        `${this.API_URL}/change-password`,
        data
      )
    );
  }

  /**
   * @method getMyMedals
   * @description Obtiene el listado de medallas del usuario logueado.
   * @returns {Promise<UserMedalDto[]>}
   */
  async getMyMedals(): Promise<UserMedalDto[]> {
    return firstValueFrom(this.http.get<UserMedalDto[]>(`${this.API_URL}/me/medals`));
  }
}

import { patchState, signalStore, withMethods, withState } from '@ngrx/signals';
import { rxMethod } from '@ngrx/signals/rxjs-interop';
import { inject } from '@angular/core';
import { DbHelperService } from '../services/db-helper.service';
import { pipe, tap, scan } from 'rxjs';
import { IRouteSighting } from '../../../../../shared/models/routes.interface';

import { IBirdSearch } from '../models/birds.interfaces';
import { GeoLocation, GeographyService } from '../services/geography.service';

export interface ActiveRouteState {
  isTracking: boolean;
  currentRouteId: string | null;
  currentPath: [number, number][]; // [Lng, Lat]
  totalDistance: number; // in km
  sightingsLog: (IRouteSighting & { birdInfo?: Partial<IBirdSearch> })[];
  startTime: string | null;
  departments: GeoLocation[];
  municipalities: GeoLocation[];
}

export interface RouteEntity {
  id: string;
  start_time: string;
  end_time?: string;
  total_km?: number;
  path_geojson?: string;
  route_type?: string;
  name?: string;
  comments?: string;
  status?: string;
  sync_status?: string;
}

const initialState: ActiveRouteState = {
  isTracking: false,
  currentRouteId: null,
  currentPath: [],
  totalDistance: 0,
  sightingsLog: [],
  startTime: null,
  departments: [],
  municipalities: [],
};

/**
 * @description Haversine formula to calculate the distance between two coordinates in km
 */
function calculateDistance(coord1: [number, number], coord2: [number, number]): number {
  const R = 6371; // Radius of the earth in km
  const dLat = (coord2[1] - coord1[1]) * (Math.PI / 180);
  const dLon = (coord2[0] - coord1[0]) * (Math.PI / 180);
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(coord1[1] * (Math.PI / 180)) *
      Math.cos(coord2[1] * (Math.PI / 180)) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return R * c;
}

/**
 * @sdd
 * @description State management for the GPS tracking routes module using NgRx SignalStore.
 * @io Dispatches state to Dual-View UI and triggers SQLite persistence.
 */
export const ActiveRouteStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withMethods((store, db = inject(DbHelperService), geoService = inject(GeographyService)) => ({

    async startTracking(routeId: string) {
      const startIso = new Date().toISOString();
      patchState(store, {
        isTracking: true,
        currentRouteId: routeId,
        currentPath: [],
        totalDistance: 0,
        sightingsLog: [],
        startTime: startIso,
      });

      // Persist empty route skeleton immediately (FK anchor for sightings)
      console.log('[ActiveRouteStore] Iniciando ruta:', routeId);
      await db.run(
        `INSERT INTO routes (id, start_time, total_km, duration_mins, sync_status, status) VALUES (?, ?, 0.0, 0, ?, ?)`,
        [routeId, startIso, 'pending_sync', 'DRAFT']
      );
      // CRITICAL on Web: flush in-memory WAL to IndexedDB
      await db.saveToStore();
      console.log('[ActiveRouteStore] Ruta esqueleto guardada y persistida en disco.');
    },

    async loadRoute(routeId: string, isTracking: boolean) {
      console.log('[ActiveRouteStore] Cargando ruta existente:', routeId);
      const routes = await db.query('SELECT * FROM routes WHERE id = ?', [routeId]);
      if (!routes || routes.length === 0) return;
      const route = routes[0] as unknown as RouteEntity;

      let currentPath: [number, number][] = [];
      try {
        const pathGeoJson = route.path_geojson ? JSON.parse(route.path_geojson) : { coordinates: [] };
        currentPath = pathGeoJson.coordinates || [];
      } catch(e: unknown) {}

      const sightings = await db.query(`
        SELECT rs.*, b.common_name, b.scientific_name 
        FROM route_sightings rs 
        LEFT JOIN birds b ON rs.bird_id = b.id 
        WHERE rs.route_id = ? ORDER BY rs.timestamp DESC
      `, [routeId]) || [];

      const mappedSightings = (sightings as Record<string, string>[]).map((s: Record<string, string>) => ({
        ...s,
        birdInfo: {
          common_name: s['common_name'],
          scientific_name: s['scientific_name']
        }
      })) as unknown as (IRouteSighting & { birdInfo?: Partial<IBirdSearch> })[];

      patchState(store, {
        isTracking: isTracking,
        currentRouteId: routeId,
        currentPath: currentPath,
        totalDistance: route.total_km || 0,
        sightingsLog: mappedSightings,
        startTime: route.start_time || null,
      });
    },

    async stopTracking(payload: { routeName: string, routeType: string, notes: string, status: 'DRAFT' | 'COMPLETED', departmentId?: number | null, municipalityId?: number | null }) {
      const routeId = store.currentRouteId();
      if (!routeId) {
        console.error('[ActiveRouteStore] stopTracking: No hay routeId activo. Abortando.');
        return;
      }

      const endTime = new Date().toISOString();
      const pathGeoJson = JSON.stringify({ type: 'LineString', coordinates: store.currentPath() || [] });
      const safeDistance = Number(store.totalDistance()) || 0;

      console.log('[ActiveRouteStore] Guardando ruta:', routeId, 'status:', payload.status);

      await db.run(
        `UPDATE routes SET end_time = ?, route_type = ?, total_km = ?, path_geojson = ?, name = ?, comments = ?, status = ?, department_id = ?, municipality_id = ? WHERE id = ?`,
        [
          endTime, 
          payload.routeType || 'Desplazamiento', 
          safeDistance,
          pathGeoJson, 
          payload.routeName || 'Ruta sin nombre', 
          payload.notes || '', 
          payload.status,
          payload.departmentId || null,
          payload.municipalityId || null,
          routeId
        ]
      );

      // CRITICAL on Web: flush in-memory WAL to IndexedDB
      await db.saveToStore();
      console.log('[ActiveRouteStore] Ruta finalizada y persistida en disco correctamente.');

      patchState(store, {
        isTracking: false,
        currentRouteId: null,
        currentPath: [],
        totalDistance: 0,
        sightingsLog: [],
        startTime: null,
      });
    },

    /**
     * @description RxJS Effect for tracking positions.
     * Uses `scan` to accumulate distance using Haversine formula without mutating global variables.
     */
    addPosition: rxMethod<[number, number]>(
      pipe(
        scan<[number, number], { coord: [number, number]; distance: number; isFirst: boolean }>(
          (acc, newCoord) => {
            if (acc.isFirst) {
              return { coord: newCoord, distance: 0, isFirst: false };
            }
            const dist = calculateDistance(acc.coord, newCoord);
            return { coord: newCoord, distance: dist, isFirst: false };
          },
          { coord: [0, 0], distance: 0, isFirst: true }
        ),
        tap(({ coord, distance }) => {
          patchState(store, (state) => ({
            currentPath: [...state.currentPath, coord],
            totalDistance: state.totalDistance + distance,
          }));
        })
      )
    ),

    /**
     * @description Adds a sighting log attached to the current GPS route.
     * Persists instantly to SQLite.
     */
    async addSighting(birdId: string, quantity: number = 1, details: string = '', birdInfo?: Partial<IBirdSearch>) {
      const routeId = store.currentRouteId();
      if (!routeId) return;

      const path = store.currentPath();
      // Si no hay fix GPS aún, usamos (0,0) para no perder el registro del avistamiento
      const lastCoord: [number, number] = path.length > 0 ? path[path.length - 1] : [0, 0];
      const newSighting: IRouteSighting & { birdInfo?: Partial<IBirdSearch> } = {
        id: crypto.randomUUID(),
        route_id: routeId,
        bird_id: birdId,
        lng: lastCoord[0],
        lat: lastCoord[1],
        timestamp: new Date().toISOString(),
        quantity,
        details,
        sync_status: 'pending_sync',
        birdInfo
      };

      // 1. Update State
      patchState(store, (state) => {
        // Group similar sightings (as requested in SDD acceptance criteria)
        const existingIndex = state.sightingsLog.findIndex((s) => s.bird_id === birdId);
        if (existingIndex > -1) {
          const updatedLog = [...state.sightingsLog];
          updatedLog[existingIndex] = {
            ...updatedLog[existingIndex],
            quantity: updatedLog[existingIndex].quantity + quantity
          };
          // Note: we might overwrite details or append them, let's keep it simple for now
          return { sightingsLog: updatedLog };
        }
        return { sightingsLog: [...state.sightingsLog, newSighting] };
      });

      // 2. Persist to SQLite
      const lat = Number(newSighting.lat) || 0.0;
      const lng = Number(newSighting.lng) || 0.0;
      const qty = Number(newSighting.quantity) || 1;

      await db.run(
        `INSERT INTO route_sightings (id, route_id, bird_id, lat, lng, timestamp, quantity, details, sync_status) 
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET quantity = quantity + ?`,
        [
          newSighting.id,
          newSighting.route_id,
          newSighting.bird_id,
          lat,
          lng,
          newSighting.timestamp,
          qty,
          newSighting.details || '',
          newSighting.sync_status || 'pending_sync',
          qty,
        ]
      );
    },

    async loadDepartments(): Promise<void> {
      try {
        const depts = await geoService.getDepartments();
        patchState(store, { departments: depts });
      } catch (err) {
        console.error('Error loading departments in ActiveRouteStore', err);
      }
    },

    async loadMunicipalities(departmentId: number): Promise<void> {
      try {
        const munis = await geoService.getMunicipalities(departmentId);
        patchState(store, { municipalities: munis });
      } catch (err) {
        console.error('Error loading municipalities in ActiveRouteStore', err);
      }
    }

  }))
);

import { inject } from '@angular/core';
import { signalStore, withState, withMethods, patchState } from '@ngrx/signals';
import { AuthService } from '../services/auth.service';
import { User, AuthResponse } from '../models/auth.models';

export type AuthState = {
  user: User | null;
  accessToken: string | null;
  isLoading: boolean;
};

const initialState: AuthState = {
  user: null,
  accessToken: null,
  isLoading: false,
};

/**
 * @class AuthStore
 * @description Almacén centralizado y reactivo para la sesión usando NgRx SignalStore.
 */
export const AuthStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withMethods((store, authService = inject(AuthService)) => ({

    async login(identifier: string, pass: string, remember: boolean = false): Promise<AuthResponse> {
      patchState(store, { isLoading: true });
      try {
        const response = await authService.login(identifier, pass, remember);
        patchState(store, { 
          user: response.user, 
          accessToken: response.access_token, 
          isLoading: false 
        });
        return response;
      } catch (err) {
        patchState(store, { isLoading: false });
        throw err;
      }
    },

    async register(userData: Partial<User>): Promise<User> {
      patchState(store, { isLoading: true });
      try {
        const user = await authService.register(userData);
        patchState(store, { isLoading: false });
        return user;
      } catch (err) {
        patchState(store, { isLoading: false });
        throw err;
      }
    },

    async logout(): Promise<void> {
      patchState(store, { isLoading: true });
      await authService.logout();
      patchState(store, { user: null, accessToken: null, isLoading: false });
    },

    syncFromService() {
      patchState(store, { 
        user: authService.currentUser(), 
        accessToken: authService.getToken() 
      });
    }

  }))
);

/**
 * @sdd
 * @description Global State Management for Bird Search using NgRx SignalStore.
 * @io Injects NetworkService and DbHelperService. Exposes activeFilters, filteredBirdsList, flatList, totalFound, and methods to update filters.
 * @edge_cases Handles SQLite initialization delay and complex multi-parameter filtering efficiently.
 */
import { signalStore, withState, withMethods, withComputed, patchState } from '@ngrx/signals';
import { inject, computed } from '@angular/core';
import { IBirdSearch } from '../models/birds.interfaces';
import { DbHelperService } from '../services/db-helper.service';
import { NetworkService } from '../services/network.service';

export interface FilterLabel {
  key: keyof IBirdSearch | 'altitude';
  label: string;
}

export type ListItem =
  | { type: 'HEADER'; label: string }
  | { type: 'BIRD'; data: IBirdSearch };

interface BirdSearchState {
  birds: IBirdSearch[];
  isLoading: boolean;
  activeFilters: Partial<IBirdSearch>;
}

const initialState: BirdSearchState = {
  birds: [],
  isLoading: false,
  activeFilters: {
    min_altitude: 0,
    max_altitude: 5000,
  },
};

export const BirdSearchStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withComputed((store) => ({
    activeFilterLabels: computed<FilterLabel[]>(() => {
      const f = store.activeFilters();
      const labels: FilterLabel[] = [];

      if (f.scientific_name)
        labels.push({ key: 'scientific_name', label: f.scientific_name });

      if ((f.min_altitude ?? 0) > 0 || (f.max_altitude ?? 5000) < 5000) {
        labels.push({
          key: 'altitude',
          label: `${f.min_altitude}-${f.max_altitude}m`,
        });
      }

      if (f.conservation_status_id)
        labels.push({ key: 'conservation_status_id', label: 'Estatus Cons.' });

      if (f.viewing_difficulty)
        labels.push({
          key: 'viewing_difficulty',
          label: `Dificultad ${f.viewing_difficulty}`,
        });

      if (f.family_id)
        labels.push({ key: 'family_id', label: 'Filtro: Familia' });

      if (f.habitat_id)
        labels.push({ key: 'habitat_id', label: 'Filtro: Hábitat' });

      if (f.residency_type_id) {
        labels.push({ key: 'residency_type_id', label: 'Filtro: Residencia' });
      }

      if (f.department_id)
        labels.push({ key: 'department_id', label: 'Filtro: Dpto.' });

      if (f.size_id) {
        const sizeLabels: Record<number, string> = {
          1: 'Muy Pequeño',
          2: 'Pequeño',
          3: 'Mediano',
          4: 'Grande',
          5: 'Muy Grande',
        };
        labels.push({
          key: 'size_id' as keyof IBirdSearch,
          label: `Tamaño: ${sizeLabels[f.size_id] || 'Filtro'}`,
        });
      }

      return labels;
    }),

    filteredBirdsList: computed<IBirdSearch[]>(() => {
      const data = store.birds();
      const f = store.activeFilters();

      return data.filter((bird: IBirdSearch) => {
        const search = (f.scientific_name || f.common_name)?.toLowerCase() || '';
        const matchesSearch =
          !search ||
          bird.scientific_name.toLowerCase().includes(search) ||
          bird.common_name?.toLowerCase().includes(search);

        const matchesAlt =
          bird.min_altitude >= (f.min_altitude ?? 0) &&
          bird.max_altitude <= (f.max_altitude ?? 5000);
        const matchesStatus =
          f.conservation_status_id === undefined ||
          bird.conservation_status_id === f.conservation_status_id;
        const matchesDifficulty =
          f.viewing_difficulty === undefined ||
          bird.viewing_difficulty === f.viewing_difficulty;
        const matchesHabitat =
          f.habitat_id === undefined || bird.habitat_id === f.habitat_id;
        const matchesResidency =
          f.residency_type_id === undefined ||
          bird.residency_type_id === f.residency_type_id;
        const matchesFamily =
          f.family_id === undefined || bird.family_id === f.family_id;
        const matchesOrder =
          f.order_id === undefined || bird.order_id === f.order_id;

        const matchesDept =
          f.department_id === undefined ||
          (() => {
            if (!bird.department_ids) return false;
            return bird.department_ids
              .split(',')
              .map((id: string) => parseInt(id, 10))
              .includes(f.department_id);
          })();

        const matchesSize =
          f.size_id === undefined ||
          (() => {
            const sizes = [
              { id: 1, min: 1, max: 10 },
              { id: 2, min: 11, max: 25 },
              { id: 3, min: 26, max: 50 },
              { id: 4, min: 51, max: 75 },
              { id: 5, min: 76, max: 999 },
            ];
            const current = sizes.find((s) => s.id === f.size_id);
            if (!current) return true;
            const bSize = bird.size ?? 0;
            return bSize >= current.min && bSize <= current.max;
          })();

        return (
          matchesSearch &&
          matchesAlt &&
          matchesStatus &&
          matchesDifficulty &&
          matchesHabitat &&
          matchesResidency &&
          matchesDept &&
          matchesFamily &&
          matchesOrder &&
          matchesSize
        );
      });
    }),
  })),
  withComputed((store) => ({
    totalFound: computed<number>(() => store.filteredBirdsList().length),
    flatList: computed<ListItem[]>(() => {
      const list = store.filteredBirdsList();
      const groups: Record<string, IBirdSearch[]> = {};

      list.forEach((bird: IBirdSearch) => {
        const groupName = bird.family_description || 'OTRAS FAMILIAS';
        if (!groups[groupName]) groups[groupName] = [];
        groups[groupName].push(bird);
      });

      const flat: ListItem[] = [];
      Object.keys(groups)
        .sort()
        .forEach((group: string) => {
          flat.push({ type: 'HEADER', label: group.toUpperCase() });
          groups[group].forEach((bird: IBirdSearch) =>
            flat.push({ type: 'BIRD', data: bird })
          );
        });
      return flat;
    })
  })),
  withMethods((store, db = inject(DbHelperService), network = inject(NetworkService)) => ({
    updateFilters(partialFilters: Partial<IBirdSearch>) {
      patchState(store, (state) => ({
        activeFilters: { ...state.activeFilters, ...partialFilters }
      }));
    },

    clearFilters() {
      patchState(store, {
        activeFilters: { min_altitude: 0, max_altitude: 5000 }
      });
    },

    removeFilter(key: string) {
      patchState(store, (state) => {
        const update = { ...state.activeFilters };
        if (key === 'altitude') {
          update.min_altitude = 0;
          update.max_altitude = 5000;
        } else {
          delete (update as Record<string, unknown>)[key];
        }
        return { activeFilters: update };
      });
    },

    async loadFromLocal(): Promise<void> {
      const query = `
        SELECT b.*,
               f.description as family_description,
               f.order_id,
               cs.convention as conservation_convention,
               rt.description as residency_description,
               (SELECT GROUP_CONCAT(department_id) FROM bird_departments WHERE bird_id = b.id AND sql_deleted = 0) as department_ids
        FROM birds b
        LEFT JOIN families f ON b.family_id = f.id
        LEFT JOIN conservation_statuses cs ON b.conservation_status_id = cs.id
        LEFT JOIN residency_types rt ON b.residency_type_id = rt.id
        WHERE b.sql_deleted = 0
        ORDER BY f.description ASC, b.scientific_name ASC
      `;
      try {
        const local = await db.query(query);
        if (local) {
            patchState(store, { birds: local as unknown as IBirdSearch[] });
        }
      } catch (error) {
        console.error(
          '❌ [BirdSearchStore] Error SQL en carga de catálogo:',
          error
        );
      }
    },

    async loadCatalog(): Promise<void> {
      if (!db.getSeedingStatus()) {
        setTimeout(() => this.loadCatalog(), 500);
        return;
      }
      patchState(store, { isLoading: true });
      await this.loadFromLocal();
      patchState(store, { isLoading: false });
    }
  }))
);

/**
 * @sdd
 * - [Objetivo]: Store para la gestión reactiva de la vista del Dashboard y Layout (Selector, Pajarero, Proveedor).
 * - [I/O]: Expone Signals y métodos para cambiar la vista actual.
 */
import { signalStore, withState, withMethods, patchState, withComputed } from '@ngrx/signals';
import { computed } from '@angular/core';
import { ViewMode, UserRole } from '../models/auth.models';

export interface DashboardState {
  activeViewMode: ViewMode;
}

const initialState: DashboardState = {
  activeViewMode: null,
};

export const DashboardStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withComputed((store) => ({
    currentView: computed(() => store.activeViewMode()),
  })),
  withMethods((store) => ({
    initializeFromRole(role: UserRole): void {
      if (role === UserRole.PAJARERO) {
        patchState(store, { activeViewMode: 'PAJARERO' });
      } else if (role === UserRole.PROVEEDOR) {
        patchState(store, { activeViewMode: 'PROVEEDOR' });
      } else if (role === UserRole.BOTH) {
        patchState(store, { activeViewMode: null });
      }
    },
    setMode(mode: ViewMode): void {
      patchState(store, { activeViewMode: mode });
    },
    resetDashboard(): void {
      patchState(store, { activeViewMode: null });
    }
  }))
);

/**
 * @sdd
 * - [Objetivo]: Store global para el Feed, gestionando paginación por cursor y modo offline.
 * - [I/O]: Consume HttpClient para API REST, expone estado reactivo para la UI.
 * - [Edge Cases]: Maneja la concatenación de posts al hacer scroll infinito.
 */
import { signalStore, withState, withMethods, patchState } from '@ngrx/signals';
import { inject } from '@angular/core';
import { rxMethod } from '@ngrx/signals/rxjs-interop';
import { pipe, switchMap, tap, catchError, of } from 'rxjs';
import { FeedPost } from '../../../../../shared/models/feed.model';
import { FeedService } from '../services/feed.service';

interface FeedState {
  posts: FeedPost[];
  cursor: string | null;
  isLoading: boolean;
  hasMore: boolean;
}

const initialState: FeedState = {
  posts: [],
  cursor: null,
  isLoading: false,
  hasMore: true,
};

export const FeedStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withMethods((store, feedService = inject(FeedService)) => ({

    // Método reactivo para cargar más posts
    loadMorePosts: rxMethod<void>(
      pipe(
        tap(() => patchState(store, { isLoading: true })),
        switchMap(() => {
          return feedService.getFeed(store.cursor()).pipe(
            tap((response) => {
              const mappedPosts: FeedPost[] = response.posts.map(p => ({
                ...p,
                location: (p.lat != null && p.lng != null) ? { lat: p.lat, lng: p.lng } : null
              }));
              patchState(store, (state) => ({
                posts: [...state.posts, ...mappedPosts],
                cursor: response.nextCursor,
                hasMore: !!response.nextCursor,
                isLoading: false
              }));
            }),
            catchError((err) => {
              console.error('Error fetching feed', err);
              patchState(store, { isLoading: false });
              return of(null);
            })
          );
        })
      )
    ),

    refreshFeed() {
      patchState(store, { posts: [], cursor: null, hasMore: true });
      this.loadMorePosts();
    },

    addLocalDraft(post: FeedPost) {
      patchState(store, (state) => ({
        posts: [post, ...state.posts]
      }));
    },

    publishPost: rxMethod<{ content: string; image?: string; location?: { lat: number; lng: number }; needsIdentification?: boolean }>(
      pipe(
        switchMap((payload) => {
          const formData = new FormData();
          formData.append('metadata', JSON.stringify({
            title: payload.needsIdentification ? 'Ayuda de Identificación' : 'Actualización en Comunidad',
            description: payload.content,
            lat: payload.location?.lat,
            lng: payload.location?.lng,
            needsIdentification: payload.needsIdentification
          }));

          if (payload.image) {
            // Convert dataUrl to Blob
            const arr = payload.image.split(',');
            const mimeMatch = arr[0].match(/:(.*?);/);
            const mime = mimeMatch ? mimeMatch[1] : 'image/jpeg';
            const bstr = atob(arr[1]);
            let n = bstr.length;
            const u8arr = new Uint8Array(n);
            while (n--) {
              u8arr[n] = bstr.charCodeAt(n);
            }
            const blob = new Blob([u8arr], { type: mime });
            formData.append('image', blob, 'upload.jpg');
          }

          return feedService.publishPost(formData).pipe(
            tap((rawPost) => {
              const newPost: FeedPost = {
                ...rawPost,
                location: (rawPost.lat != null && rawPost.lng != null) ? { lat: rawPost.lat, lng: rawPost.lng } : null
              };
              patchState(store, (state) => ({
                posts: [newPost, ...state.posts]
              }));
            }),
            catchError((err) => {
              console.error('Error publishing post', err);
              return of(null);
            })
          );
        })
      )
    ),

    toggleFavorite: rxMethod<string>(
      pipe(
        switchMap((postId) => {
          return feedService.toggleFavorite(postId).pipe(
            tap((res) => {
              patchState(store, (state) => ({
                posts: state.posts.map(p => {
                  if (p.id === postId) {
                    const increment = res.isFavorited ? 1 : -1;
                    return { ...p, savesCount: Math.max(0, p.savesCount + increment) };
                  }
                  return p;
                })
              }));
            }),
            catchError((err) => {
              console.error('Error toggling favorite', err);
              return of(null);
            })
          );
        })
      )
    ),

    addReply: rxMethod<{ postId: string; content: string }>(
      pipe(
        switchMap(({ postId, content }) => {
          return feedService.addReply(postId, content).pipe(
            tap(() => {
              patchState(store, (state) => ({
                posts: state.posts.map(p => p.id === postId ? { ...p, repliesCount: p.repliesCount + 1 } : p)
              }));
            }),
            catchError((err) => {
              console.error('Error adding reply', err);
              return of(null);
            })
          );
        })
      )
    )
  }))
);

/**
 * @sdd
 * @description Guide Store using NgRx SignalStore (Offline First).
 * @io Injects DbHelperService to load guides from SQLite into a fast dictionary format O(1).
 */
import { signalStore, withState, withMethods, patchState, withComputed } from '@ngrx/signals';
import { inject, computed } from '@angular/core';
import { IGuide } from '../../../../../shared/models/catalogs.interface';
import { GuideService } from '../services/guide.service';

export interface GuideState {
  guidesMap: Record<string, IGuide>;
  isLoading: boolean;
}

const initialState: GuideState = {
  guidesMap: {},
  isLoading: false,
};

export const GuideStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withComputed((store) => ({
    allGuides: computed(() => Object.values(store.guidesMap()).sort((a, b) => a.fullName.localeCompare(b.fullName))),
  })),
  withMethods((store, guideService = inject(GuideService)) => ({
    async loadGuides() {
      patchState(store, { isLoading: true });
      try {
        const result = await guideService.getGuides().toPromise();
        const map: Record<string, IGuide> = {};
        if (result) {
          for (const item of result) {
            map[item.id] = item;
          }
        }
        patchState(store, { guidesMap: map, isLoading: false });
      } catch (e) {
        console.error('Error cargando guías online:', e);
        patchState(store, { isLoading: false });
      }
    },
    getGuideById(id: string): IGuide | undefined {
      return store.guidesMap()[id];
    }
  }))
);

import { inject } from '@angular/core';
import { signalStore, withState, withMethods, patchState } from '@ngrx/signals';
import { UserService } from '../services/user.service';
import { AuthService } from '../services/auth.service';
import { GeographyService } from '../services/geography.service';
import { User, UserMedalDto } from '../models/auth.models';

import { GeoLocation } from '../services/geography.service';

export type ProfileState = {
  viewedUser: User | null;
  medals: UserMedalDto[];
  isLoading: boolean;
  departments: GeoLocation[];
  municipalities: GeoLocation[];
};

const initialState: ProfileState = {
  viewedUser: null,
  medals: [],
  isLoading: false,
  departments: [],
  municipalities: [],
};

/**
 * @class ProfileStore
 * @description Almacén centralizado y reactivo para la gestión de perfil y seguridad.
 * Encapsula los llamados HTTP del UserService para cumplir con el Principio de Responsabilidad Única.
 */
export const ProfileStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withMethods(
    (
      store, 
      userService = inject(UserService),
      authService = inject(AuthService),
      geoService = inject(GeographyService)
    ) => ({

      async loadProfile(id?: string | null): Promise<User | null> {
        patchState(store, { isLoading: true });
        try {
          const user = id 
            ? await userService.getProfileById(id)
            : await userService.getProfile();

          patchState(store, { viewedUser: user, isLoading: false });

          // Si es el perfil propio, actualizamos el state global de Auth
          if (!id || (authService.currentUser() && id === authService.currentUser()?.id)) {
            authService.currentUser.set(user);
          }

          return user;
        } catch (err) {
          patchState(store, { isLoading: false });
          throw err;
        }
      },

      async updateProfile(updateData: Partial<User>): Promise<User> {
        patchState(store, { isLoading: true });
        try {
          const updatedUser = await userService.updateProfile(updateData);
          patchState(store, { viewedUser: updatedUser, isLoading: false });
          authService.currentUser.set(updatedUser);
          return updatedUser;
        } catch (err) {
          patchState(store, { isLoading: false });
          throw err;
        }
      },

      async updatePassword(data: { oldPassword?: string; newPassword?: string }): Promise<{ message: string }> {
        patchState(store, { isLoading: true });
        try {
          const result = await userService.updatePassword(data);
          patchState(store, { isLoading: false });
          return result;
        } catch (err) {
          patchState(store, { isLoading: false });
          throw err;
        }
      },

      async uploadImage(file: Blob, type: 'AVATAR' | 'COVER', extension: string): Promise<string> {
        patchState(store, { isLoading: true });
        try {
          const uploadType = type === 'AVATAR' ? 'avatar' : 'cover';
          const { url } = await userService.uploadImage(file, uploadType, extension);

          const currentUser = store.viewedUser();
          if (currentUser) {
            const updated = {
              ...currentUser,
              [type === 'AVATAR' ? 'avatarUrl' : 'coverUrl']: url,
            };
            patchState(store, { viewedUser: updated });
            authService.currentUser.set(updated);
          }

          patchState(store, { isLoading: false });
          return url;
        } catch (err) {
          patchState(store, { isLoading: false });
          throw err;
        }
      },

      async loadMedals(): Promise<UserMedalDto[]> {
        patchState(store, { isLoading: true });
        try {
          const medals = await userService.getMyMedals();
          patchState(store, { medals, isLoading: false });
          return medals;
        } catch (err) {
          patchState(store, { isLoading: false });
          throw err;
        }
      },

      async loadDepartments(): Promise<void> {
        try {
          const depts = await geoService.getDepartments();
          patchState(store, { departments: depts });
        } catch (err) {
          console.error('Error loading departments', err);
        }
      },

      async loadMunicipalities(departmentId: number): Promise<void> {
        try {
          const munis = await geoService.getMunicipalities(departmentId);
          patchState(store, { municipalities: munis });
        } catch (err) {
          console.error('Error loading municipalities', err);
        }
      }

    })
  )
);

