/**
 * @sdd
 * @description Site Store using NgRx SignalStore (Offline First).
 * @io Injects DbHelperService to load sites from SQLite into a fast dictionary format O(1).
 */
import { signalStore, withState, withMethods, patchState, withComputed } from '@ngrx/signals';
import { inject, computed } from '@angular/core';
import { DbHelperService } from '../services/db-helper.service';
import { ISite } from '../../../../../shared/models/catalogs.interface';

export interface SiteState {
  sitesMap: Record<string, ISite>;
  isLoading: boolean;
}

const initialState: SiteState = {
  sitesMap: {},
  isLoading: false,
};

export const SiteStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withComputed((store) => ({
    allSites: computed(() => Object.values(store.sitesMap()).sort((a, b) => a.name.localeCompare(b.name))),
  })),
  withMethods((store, db = inject(DbHelperService)) => ({
    async loadSites() {
      patchState(store, { isLoading: true });
      try {
        const result = await db.query('SELECT * FROM sites WHERE sql_deleted = 0');
        const map: Record<string, ISite> = {};
        for (const item of result) {
          const siteRow = item as Record<string, unknown>;
          map[String(siteRow['id'])] = {
             ...siteRow,
             location: { lat: Number(siteRow['lat']), lng: Number(siteRow['lng']) },
             services: siteRow['services'] ? JSON.parse(siteRow['services'] as string) : [],
             prices: siteRow['prices'] ? JSON.parse(siteRow['prices'] as string) : {},
             routeGeoJson: siteRow['route_geo_json'] ? JSON.parse(siteRow['route_geo_json'] as string) : null
          } as unknown as ISite;
        }
        patchState(store, { sitesMap: map, isLoading: false });
      } catch (e) {
        console.error('Error cargando sitios locales:', e);
        patchState(store, { isLoading: false });
      }
    },
    getSiteById(id: string): ISite | undefined {
      return store.sitesMap()[id];
    }
  }))
);

/**
 * @sdd
 * @description Motor de Sincronización Base (Sync Queue Service) usando NgRx SignalStore.
 * @io Injects DbHelperService (SQLite) and SyncService. Pushes local changes to the backend and pulls remote changes.
 * @edge_cases Maneja pérdida de red, resolución de conflictos basada en 'last_modified' y soft-deletes ('sql_deleted').
 */
import { signalStore, withState, withMethods, patchState } from '@ngrx/signals';
import { inject } from '@angular/core';
import { DbHelperService } from '../services/db-helper.service';
import { NetworkService } from '../services/network.service';
import { SyncService } from '../services/sync.service';
import { ISyncCatalogsResponse } from '../../../../../shared/models/catalogs.interface';

export interface SyncState {
  isSyncing: boolean;
  lastSyncTimestamp: number;
  pendingChangesCount: number;
}

const initialState: SyncState = {
  isSyncing: false,
  lastSyncTimestamp: Number(localStorage.getItem('lastSyncTimestamp') || 0),
  pendingChangesCount: 0,
};

export const SyncQueueStore = signalStore(
  { providedIn: 'root' },
  withState(initialState),
  withMethods(
    (
      store,
      db = inject(DbHelperService),
      syncService = inject(SyncService),
      network = inject(NetworkService)
    ) => ({
      async calculatePendingChanges() {
        try {
          const result = await db.query(
            `SELECT COUNT(*) as count FROM sightings WHERE last_modified > ?`,
            [store.lastSyncTimestamp()]
          );
          const count = Number(result[0]?.['count']) || 0;
          patchState(store, { pendingChangesCount: count });
        } catch (error) {
          console.error('Error calculando cambios pendientes', error);
        }
      },

      async executeSyncCycle(force: boolean = false) {
        if (store.isSyncing() || !network.isOnline()) {
          console.warn('Sync omitido: Offline o ya en progreso.');
          return;
        }

        const now = Math.floor(Date.now() / 1000);
        const SYNC_INTERVAL = 5 * 60; // 5 minutos en segundos
        if (!force && (now - store.lastSyncTimestamp() < SYNC_INTERVAL)) {
          console.log(`Sync omitido: Han pasado menos de 5 minutos desde el último sync.`);
          return;
        }

        patchState(store, { isSyncing: true });

        try {
          // 1. PUSH: Enviar cambios locales al backend
          const pendingSightings = await db.query(
            `SELECT * FROM route_sightings WHERE sync_status = 'pending_sync'`
          ) || [];

          const pendingRoutes = await db.query(
            `SELECT * FROM routes WHERE sync_status = 'pending_sync' AND status = 'COMPLETED'`
          ) || [];

          // Cargar sesión para perfíles PENDING
          const session = await db.getSession();
          const pendingUsers = [];
          if (session && session.user_data) {
            const uObj = typeof session.user_data === 'string' ? JSON.parse(session.user_data) : session.user_data;
            if (uObj.sync_status === 'PENDING') {
              pendingUsers.push(uObj);
            }
          }

          if (pendingRoutes.length > 0 || pendingUsers.length > 0) {
            // Nest sightings into routes for the backend
            const nestedRoutes = pendingRoutes.map((r: any) => ({
              ...r,
              sightings: pendingSightings.filter((s: any) => s.route_id === r.id)
            }));

            const bulkPayload = { routes: nestedRoutes, users: pendingUsers };
            await syncService.pushChanges(bulkPayload).toPromise();

            // Marcar localmente como sincronizado tras éxito HTTP
            if (pendingRoutes.length > 0) {
              await db.run(`UPDATE routes SET sync_status = 'synced' WHERE sync_status = 'pending_sync' AND status = 'COMPLETED'`, []);
            }
            if (pendingSightings.length > 0) {
              await db.run(`UPDATE route_sightings SET sync_status = 'synced' WHERE sync_status = 'pending_sync'`, []);
            }
            if (pendingUsers.length > 0 && session) {
              const uObj = pendingUsers[0];
              uObj.sync_status = 'SYNCED';
              await db.saveSession(session.token, uObj);
            }
          }

          // 2. PULL: Recibir catálogos del backend
          const remoteCatalogs = await syncService.pullCatalogs(store.lastSyncTimestamp()).toPromise();

          if (remoteCatalogs) {
             // Upsert lógico para Guías
             if (remoteCatalogs.guides && remoteCatalogs.guides.length > 0) {
               for (const guide of remoteCatalogs.guides) {
                  await db.query(
                     `INSERT INTO guides (id, full_name, location, specialty, rating, photo_url, details, languages, bio, phone, last_modified, sql_deleted) 
                      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                      ON CONFLICT(id) DO UPDATE SET
                      full_name=excluded.full_name, location=excluded.location, specialty=excluded.specialty,
                      rating=excluded.rating, photo_url=excluded.photo_url, details=excluded.details,
                      languages=excluded.languages, bio=excluded.bio, phone=excluded.phone,
                      last_modified=excluded.last_modified, sql_deleted=excluded.sql_deleted
                      WHERE excluded.last_modified > guides.last_modified`,
                     [guide.id, guide.fullName, guide.location, guide.specialty, guide.rating, guide.photoUrl, guide.details, guide.languages, guide.bio, guide.phone, guide.last_modified, guide.sql_deleted ? 1 : 0]
                  );
               }
             }

             // Upsert lógico para Sitios
             if (remoteCatalogs.sites && remoteCatalogs.sites.length > 0) {
               for (const site of remoteCatalogs.sites) {
                  await db.query(
                     `INSERT INTO sites (id, name, department, rating, description, photo_url, lat, lng, route_geo_json, services, prices, expected_birds, last_modified, sql_deleted) 
                      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                      ON CONFLICT(id) DO UPDATE SET
                      name=excluded.name, department=excluded.department, rating=excluded.rating,
                      description=excluded.description, photo_url=excluded.photo_url, lat=excluded.lat, lng=excluded.lng,
                      route_geo_json=excluded.route_geo_json, services=excluded.services, prices=excluded.prices,
                      expected_birds=excluded.expected_birds,
                      last_modified=excluded.last_modified, sql_deleted=excluded.sql_deleted
                      WHERE excluded.last_modified > sites.last_modified`,
                     [
                        site.id, site.name, site.department, site.rating, site.description, 
                        site.photoUrl, site.location?.lat || 0, site.location?.lng || 0, 
                        JSON.stringify(site.routeGeoJson), JSON.stringify(site.services), 
                        JSON.stringify(site.prices), JSON.stringify(site.expectedBirds), 
                        site.last_modified, site.sql_deleted ? 1 : 0
                     ]
                  );
               }
             }

             // Upsert para Site Birds (Opcional, relación)
             if (remoteCatalogs.site_birds && remoteCatalogs.site_birds.length > 0) {
               for (const sb of remoteCatalogs.site_birds) {
                  await db.query(
                     `INSERT OR IGNORE INTO site_birds (site_id, bird_id) VALUES (?, ?)`,
                     [sb.site_id, sb.bird_id]
                  );
               }
             }

             // Upsert Geografía
             if (remoteCatalogs.departments && remoteCatalogs.departments.length > 0) {
               for (const dep of remoteCatalogs.departments) {
                 await db.query(`INSERT OR REPLACE INTO departments (id, name, sql_deleted) VALUES (?, ?, ?)`, 
                   [dep.id, dep.name, dep.sql_deleted ? 1 : 0]);
               }
             }

             if (remoteCatalogs.municipalities && remoteCatalogs.municipalities.length > 0) {
               for (const mun of remoteCatalogs.municipalities) {
                 await db.query(`INSERT OR REPLACE INTO municipalities (id, department_id, name, sql_deleted) VALUES (?, ?, ?, ?)`, 
                   [mun.id, mun.department_id, mun.name, mun.sql_deleted ? 1 : 0]);
               }
             }

             // Upsert Aves (El catálogo maestro vital)
             if (remoteCatalogs.birds && remoteCatalogs.birds.length > 0) {
               for (const bird of remoteCatalogs.birds) {
                 await db.query(
                   `INSERT OR REPLACE INTO birds (id, scientific_name, english_name, common_name, min_altitude, max_altitude, viewing_difficulty, size, environment, behavior, colors, authority, gbif_link, wikiaves_link, ebird_link, other_sources, base_image, image_copyright, habitat_id, conservation_status_id, family_id, residency_type_id, feeding_type_id, beak_morphology_id, wing_morphology_id, tail_morphology_id, leg_morphology_id, additional_info_id, sql_deleted, last_modified) 
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`, 
                   [bird.id, bird.scientific_name, bird.english_name, bird.common_name, bird.min_altitude, bird.max_altitude, bird.viewing_difficulty, bird.size, bird.environment, bird.behavior, bird.colors, bird.authority, bird.gbif_link, bird.wikiaves_link, bird.ebird_link, bird.other_sources, bird.base_image, bird.image_copyright, bird.habitat_id, bird.conservation_status_id, bird.family_id, bird.residency_type_id, bird.feeding_type_id, bird.beak_morphology_id, bird.wing_morphology_id, bird.tail_morphology_id, bird.leg_morphology_id, bird.additional_info_id, bird.sql_deleted ? 1 : 0, Math.floor(new Date(bird.last_modified).getTime() / 1000)]
                 );
               }
             }
          }

          const newTimestamp = Math.floor(Date.now() / 1000);
          localStorage.setItem('lastSyncTimestamp', newTimestamp.toString());
          patchState(store, { 
             isSyncing: false, 
             lastSyncTimestamp: newTimestamp,
             pendingChangesCount: 0 
          });

        } catch (error) {
          console.error('Error crítico durante el ciclo de sincronización', error);
          patchState(store, { isSyncing: false });
        }
      },
    })
  )
);

