export class BirdSearchPage {
  public readonly searchStore = inject(BirdSearchStore);
  public readonly network = inject(NetworkService);
  private readonly modalCtrl = inject(ModalController);
  private readonly cdr = inject(ChangeDetectorRef);

  /** @property {string} currentHeader - Almacena la etiqueta de la familia taxonómica actualmente visible en el top del scroll. */
  public currentHeader: string = '';

  /**
   * @method ionViewDidEnter
   * @description Hook de ciclo de vida de Ionic encargado de inicializar el catálogo de aves de forma perezosa si la lista está vacía.
   */
  ionViewDidEnter(): void {
    if (this.searchStore.totalFound() === 0) {
      this.searchStore.loadCatalog();
    }
  }

  /**
   * @method onSearch
   * @description Modifica reactivamente los filtros de búsqueda por coincidencia textual en nombres comunes o científicos.
   * @param {any} event - Evento emitido por el componente ion-searchbar.
   */
  onSearch(event: CustomEvent): void {
    const query = (event.target as HTMLInputElement).value;
    this.searchStore.updateFilters({ scientific_name: query });
    this.currentHeader = '';
  }

  /**
   * @method removeFilter
   * @description Remueve selectivamente un criterio de filtrado activo desde los chips de control de la cabecera.
   * @param {string} key - Propiedad clave del filtro a remover en la interfaz de usuario.
   */
  removeFilter(key: string): void {
    this.searchStore.removeFilter(key);
    this.currentHeader = '';
  }

  /**
   * @method onScrollIndexChange
   * @description Rastrea de forma reactiva el índice de scroll virtual superior para calcular y fijar la familia taxonómica flotante (Sticky Header).
   * @param {number} index - Índice del primer elemento visible dentro del Viewport actual.
   */
  onScrollIndexChange(index: number): void {
    const list: ListItem[] = this.searchStore.flatList();
    if (!list || list.length === 0) {
      this.currentHeader = '';
      this.cdr.markForCheck();
      return;
    }

    for (let i = index; i >= 0; i--) {
      const item = list[i];
      if (item && item.type === 'HEADER') {
        if (this.currentHeader !== item.label) {
          this.currentHeader = item.label;
          this.cdr.markForCheck();
        }
        return;
      }
    }

    const firstHeader = list.find(
      (item): item is { type: 'HEADER'; label: string } =>
        item.type === 'HEADER'
    );
    this.currentHeader = firstHeader ? firstHeader.label : '';
    this.cdr.markForCheck();
  }

  /**
   * @method openGeneralFilter
   * @description Despliega el modal de filtros generales avanzados con soporte nativo de breakpoints de tipo Bottom Sheet.
   */
  async openGeneralFilter(): Promise<void> {
    const modal = await this.modalCtrl.create({
      component: GeneralFilterComponent,
      handle: true,
    });
    return await modal.present();
  }

  /**
   * @method openModal
   * @description Abre el modal categórico pasando el parámetro initialTab mapeado de forma consistente con las tablas y segmentos.
   * @param {string} tab - Identificador visual de la pestaña seleccionada por el usuario en el listado horizontal.
   */
  async openModal(tab: string): Promise<void> {
    const tabMap: Record<string, string> = {
      family: 'orders',
      habitat: 'habitats',
      residency: 'residency',
      size: 'sizes',
      departments: 'departments',
    };
    const modal = await this.modalCtrl.create({
      component: CategoricalFilterComponent,
      componentProps: { initialTab: tabMap[tab] || 'orders' },
    });
    return await modal.present();
  }

  /**
   * @method openBirdDetail
   * @description Redirecciona la experiencia del usuario hacia la ficha técnica extendida del espécimen seleccionado.
   * @param {IBirdSearch} bird - Estructura de datos del ave seleccionada.
   */
  async openBirdDetail(bird: IBirdSearch): Promise<void> {
    // Mapeo básico de IBirdSearch a BirdTaxonomy para la vista
    const mappedTaxonomy: BirdTaxonomy = {
      id: bird.id.toString(),
      scientificName: bird.scientific_name,
      englishName: bird.english_name,
      spanishName: bird.common_name || bird.scientific_name,
      order: 'Desconocido',
      family: bird.family_description || 'Desconocida',
      vulnerabilityStatus: 'LC',
      difficultyToSpot: 3,
      altitudeRange: { min: 0, max: 4000 },
      diet: 'Omnívora',
      sizeCm: 25,
      habitat: 'Varios',
      residenceStatus: 'Residente',
      behavior: 'Diurno',
      morphologyDescription: 'Descripción en construcción...',
      externalLinks: []
    };

    const modal = await this.modalCtrl.create({
      component: BirdEncyclopediaViewComponent,
      componentProps: { bird: mappedTaxonomy },
      breakpoints: [0, 0.7, 1],
      initialBreakpoint: 0.7
    });
    await modal.present();
  }

  /**
   * @method trackByItem
   * @description Optimizador algorítmico del rendimiento de renderizado en el DOM de Angular para colecciones polimórficas complejas.
   */
  trackByItem(index: number, item: ListItem): string | number {
    return item.type === 'HEADER' ? item.label : item.data.id;
  }
}

import { Component, inject, OnInit, input, signal, effect } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ModalController, IonHeader, IonToolbar, IonTitle, IonButtons, IonButton, IonSegment, IonSegmentButton, IonContent, IonIcon, IonFooter, IonModal } from '@ionic/angular';
import { FormsModule } from '@angular/forms';
import { DbHelperService } from '../../../../../core/services/db-helper.service';
import { BirdSearchStore } from '../../../../../core/stores/bird-search.store';
import { IBirdSearch } from '../../../../../core/models/birds.interfaces';

export interface ICategoricalChild {
  id: number;
  description: string;
  order_id: number;
  total_aves?: number;
  tipos_aves?: string;
}

export interface ICategoricalItem {
  id: number;
  description?: string;
  departments?: string;
  children?: ICategoricalChild[];
}

export type BirdNumericFilterKey =
  | 'habitat_id'
  | 'residency_type_id'
  | 'department_id';

/**
 * @sdd
 * - [Objetivo]: Modal de filtros estructurados por categorías con ordenamiento estricto A-Z.
 * - [I/O - Reusabilidad]: Input `initialTab`.
 * - [Edge Cases - UI]: Maneja múltiples vistas de categorías.
 */
@Component({
  selector: 'app-categorical-filter',
  standalone: true,
  imports: [CommonModule, FormsModule, IonHeader, IonToolbar, IonTitle, IonButtons, IonButton, IonSegment, IonSegmentButton, IonContent, IonIcon, IonFooter, IonModal],
  templateUrl: './categorical-filter.component.html',
  styleUrls: ['./categorical-filter.component.scss'],
})
export class CategoricalFilterComponent implements OnInit {
  private readonly modalCtrl = inject(ModalController);
  private readonly db = inject(DbHelperService);
  private readonly searchStore = inject(BirdSearchStore);

  /** Pestaña inicial a cargar en el filtro */
  initialTab = input<string>();

  constructor() {
    effect(() => {
      const tab = this.initialTab();
      if (tab) {
        this.activeTab.set(tab);
        this.loadData();
      }
    }, { allowSignalWrites: true });
  }

  public activeTab = signal<string>('orders');
  public list = signal<ICategoricalItem[]>([]);
  public selection = signal<Partial<IBirdSearch>>({});

  async ngOnInit(): Promise<void> {
    this.selection.set({ ...this.searchStore.activeFilters() });
  }

  /**
   * @method loadData
   * @description Realiza consultas dinámicas inyectando cláusulas ORDER BY automáticas para ordenar las opciones de la A a la Z.
   */
  async loadData(): Promise<void> {
    try {
      if (this.activeTab() === 'orders') {
        const orders = (await this.db.query(
          'SELECT * FROM orders WHERE sql_deleted = 0 ORDER BY description ASC'
        )) as ICategoricalItem[];
        const families = (await this.db.query(
          'SELECT * FROM families WHERE sql_deleted = 0 ORDER BY description ASC'
        )) as ICategoricalChild[];

        this.list.set(orders.map((o: ICategoricalItem) => ({
          ...o,
          children: families.filter(
            (f: ICategoricalChild) => f.order_id === o.id
          ),
        })));
      } else {
        const tableMap: Record<string, string> = {
          habitats: 'habitats',
          residency: 'residency_types',
          departments: 'departments',
        };
        const table = tableMap[this.activeTab()];
        if (table) {
          // Determina dinámicamente si el campo descriptor alfabético es 'departments' o 'description'
          const orderField =
            table === 'departments' ? 'departments' : 'description';
          this.list.set((await this.db.query(
            `SELECT * FROM ${table} WHERE sql_deleted = 0 ORDER BY ${orderField} ASC`
          )) as ICategoricalItem[]);
        }
      }
    } catch (e) {
      console.error(
        '❌ [CategoricalFilter] Error en carga ordenada de filtros:',
        e
      );
    }
  }

  public selectOrder(order: ICategoricalItem): void {
    this.selection.update(s => {
        const newOrderId = s.order_id === order.id ? undefined : order.id;
        return {
            ...s,
            order_id: newOrderId,
            family_id: newOrderId === undefined ? undefined : s.family_id
        };
    });
  }

  public selectFamily(familyId: number): void {
    this.selection.update(s => ({
        ...s,
        family_id: s.family_id === familyId ? undefined : familyId
    }));
  }

  public selectGeneric(item: ICategoricalItem): void {
    const keyMap: Record<string, BirdNumericFilterKey> = {
      habitats: 'habitat_id',
      residency: 'residency_type_id',
      departments: 'department_id',
    };
    const key = keyMap[this.activeTab()];
    if (key) {
      this.selection.update(s => ({
          ...s,
          [key]: s[key] === item.id ? undefined : item.id
      }));
    }
  }

  public isSelected(item: ICategoricalItem): boolean {
    const currentSelection = this.selection();
    if (this.activeTab() === 'orders') {
      return currentSelection.family_id === item.id;
    }
    const keyMap: Record<string, BirdNumericFilterKey> = {
      habitats: 'habitat_id',
      residency: 'residency_type_id',
      departments: 'department_id',
    };
    const key = keyMap[this.activeTab()];
    return key ? currentSelection[key] === item.id : false;
  }

  public apply(): void {
    // Para replicar el .set() anterior, actualizamos todos los filtros
    this.searchStore.updateFilters({ ...this.selection() });
    this.modalCtrl.dismiss();
  }

  public dismiss(): void {
    this.modalCtrl.dismiss();
  }
}

import {
  Component,
  inject,
  OnInit,
  ChangeDetectorRef,
  NgZone,
  signal,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { ModalController, IonHeader, IonToolbar, IonTitle, IonButtons, IonButton, IonContent, IonLabel, IonIcon, IonRange, IonModal } from '@ionic/angular';
import { Geolocation } from '@capacitor/geolocation';
import { BirdSearchStore } from './../../../../../core/stores/bird-search.store';
import { DbHelperService } from './../../../../../core/services/db-helper.service';
import { FormsModule } from '@angular/forms';
import { ITamanio } from './../../../../../core/models/birds.interfaces';

/**
 * @class GeneralFilterComponent
 * @description Gestiona las configuraciones de filtros avanzados unificados (Alturas, Estatus, Dificultad y Tamaños).
 */
@Component({
  selector: 'app-general-filter',
  standalone: true,
  imports: [CommonModule, FormsModule, IonHeader, IonToolbar, IonTitle, IonButtons, IonButton, IonContent, IonLabel, IonIcon, IonRange, IonModal],
  templateUrl: './general-filter.component.html',
  styleUrls: ['./general-filter.component.scss'],
})
export class GeneralFilterComponent implements OnInit {
  private readonly modalCtrl = inject(ModalController);
  private readonly searchStore = inject(BirdSearchStore);
  private readonly db = inject(DbHelperService);
  private readonly cdr = inject(ChangeDetectorRef);
  private readonly ngZone = inject(NgZone);

  selectedStatus = signal<number | null>(null);
  selectedDifficulty = signal<number | null>(null);
  selectedSize = signal<number | null>(null); 
  heightRange = signal({ lower: 0, upper: 5000 });

  conservationStatuses = signal<{id: number, convention: string, description: string, image: string}[]>([]);

  difficultyOptions = [
    { id: 1, name: 'Muy Fácil', icon: 'eye' },
    { id: 2, name: 'Fácil', icon: 'eye' },
    { id: 3, name: 'Moderado', icon: 'eye-off' },
    { id: 4, name: 'Muy Difícil', icon: 'eye-off' },
  ];

  /** @property aTamanios Estructura de datos estática inyectada de forma directa sin llamadas a base de datos. */
  public readonly aTamanios: ITamanio[] = [
    {
      id: 1,
      descripcion: 'Muy Pequeño (Hasta 10cm)',
      tamanioMin: 1,
      tamanioMax: 10,
    },
    {
      id: 2,
      descripcion: 'Pequeño (De 11cm a 25cm)',
      tamanioMin: 11,
      tamanioMax: 25,
    },
    {
      id: 3,
      descripcion: 'Mediano (De 26cm a 50cm)',
      tamanioMin: 26,
      tamanioMax: 50,
    },
    {
      id: 4,
      descripcion: 'Grande (De 51cm a 75cm)',
      tamanioMin: 51,
      tamanioMax: 75,
    },
    {
      id: 5,
      descripcion: 'Muy Grande (Más de 75cm)',
      tamanioMin: 76,
      tamanioMax: 999,
    },
  ];

  /**
   * @method ngOnInit
   * @description Sincroniza las referencias locales del Bottom Sheet con los Signals vigentes de la página principal.
   */
  async ngOnInit(): Promise<void> {
    this.selectedStatus.set(
      this.searchStore.activeFilters().conservation_status_id || null
    );

    this.selectedDifficulty.set(
      this.searchStore.activeFilters().viewing_difficulty || null
    );

    this.selectedSize.set(this.searchStore.activeFilters().size_id || null);

    this.heightRange.set({
      lower: this.searchStore.activeFilters().min_altitude || 0,
      upper: this.searchStore.activeFilters().max_altitude || 5000,
    });

    try {
      const statuses = await this.db.query(
        'SELECT * FROM conservation_statuses WHERE sql_deleted = 0'
      );
      this.conservationStatuses.set(statuses as {id: number, convention: string, description: string, image: string}[]);
      this.cdr.detectChanges();
    } catch (e) {
      console.warn('Error cargando estados:', e);
    }
  }

  /**
   * @method getGPSHeight
   * @description Captura las coordenadas de latitud/altitud mediante Capacitor Geolocation forzando la detección en zona.
   */
  async getGPSHeight(): Promise<void> {
    try {
      const position = await Geolocation.getCurrentPosition();
      let altitude = Math.round(position.coords.altitude || 0);

      if (altitude < 0) altitude = 0;
      if (altitude > 5000) altitude = 5000;

      this.ngZone.run(() => {
        this.heightRange.set({
          lower: altitude,
          upper: this.heightRange().upper,
        });
      });
    } catch (e) {
      console.warn('GPS no disponible:', e);
    }
  }

  /**
   * @method onRangeChange
   * @description Sincroniza los cambios del control ion-range sobre el objeto estructural.
   * @param {any} ev Evento nativo emitido por el slider.
   */
  onRangeChange(ev: CustomEvent): void {
    this.heightRange.set(ev.detail?.value);
  }

  /**
   * @method getSizeTitle
   * @description Extrae de forma segura el adjetivo descriptivo del tamaño eliminando las cotas métricas entre paréntesis.
   * @param {string} desc Cadena descriptiva total de la entidad.
   */
  getSizeTitle(desc: string): string {
    const idx = desc.indexOf(' (');
    return idx !== -1 ? desc.substring(0, idx) : desc;
  }

  /**
   * @method getSizeSubtitle
   * @description Extrae las cotas métricas secundarias encerradas entre paréntesis para utilizarlas como subtítulo de la tarjeta.
   * @param {string} desc Cadena descriptiva total de la entidad.
   */
  getSizeSubtitle(desc: string): string {
    const idx = desc.indexOf(' (');
    return idx !== -1 ? desc.substring(idx + 1) : '';
  }

  /**
   * @method applyFilters
   * @description Empuja inmutablemente las configuraciones finales a los Signals reactivos de la app y destruye el modal.
   */
  applyFilters(): void {
    this.searchStore.updateFilters({
      min_altitude: this.heightRange().lower,
      max_altitude: this.heightRange().upper,
      conservation_status_id: this.selectedStatus() ?? undefined,
      viewing_difficulty: this.selectedDifficulty() ?? undefined,
      size_id: this.selectedSize() ?? undefined,
    });
    this.modalCtrl.dismiss();
  }

  /**
   * @method dismiss
   * @description Destruye el modal actual sin aplicar ninguna mutación de filtros.
   */
  dismiss(): void {
    this.modalCtrl.dismiss();
  }
}

import {
  Component,
