    .chat-input { --background: #f1f5f9; --padding-start: 16px; --padding-end: 16px; --padding-top: 12px; --padding-bottom: 12px; --border-radius: 20px; font-size: 15px; margin: 0; }
    :host-context(body.dark) .chat-input { --background: #1e293b; }
    .send-btn { margin-bottom: 4px; margin-left: 8px; }
  `],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class PostRepliesComponent implements OnInit {
  @Input() post!: FeedPost;

  readonly icons = {
    closeOutline,
    sendOutline,
    chatbubblesOutline
  };

  private modalCtrl = inject(ModalController);
  private feedService = inject(FeedService);
  private feedStore = inject(FeedStore);

  replies = signal<FeedReply[]>([]);
  isLoading = signal<boolean>(true);
  isSending = signal<boolean>(false);
  newReplyContent = '';

  ngOnInit() {
    this.loadReplies();
  }

  loadReplies() {
    this.isLoading.set(true);
    this.feedService.getReplies(this.post.id).subscribe({
      next: (data) => {
        this.replies.set(data);
        this.isLoading.set(false);
      },
      error: (err) => {
        console.error('Error fetching replies', err);
        this.isLoading.set(false);
      }
    });
  }

  sendReply() {
    if (!this.newReplyContent.trim()) return;

    this.isSending.set(true);
    const content = this.newReplyContent.trim();

    // Call the global store to increment count
    this.feedStore.addReply({ postId: this.post.id, content });

    // We can optimistically push it locally to the replies array
    const optimisticReply: FeedReply = {
      id: Date.now().toString(),
      postId: this.post.id,
      authorId: 'me',
      authorName: 'Yo',
      content: content,
      createdAt: new Date().toISOString()
    };

    this.replies.update(r => [...r, optimisticReply]);
    this.newReplyContent = '';
    this.isSending.set(false);
  }

  close() {
    this.modalCtrl.dismiss();
  }
}

