/**
 * @class MainLayoutPage
 * @description Componente de Orquestación Visual (Shell).
 * Gestiona el menú lateral, la navegación por pestañas (Tabs) y la sincronización de perfil.
 * @author Gemini (Orquestador SDD)
 */
@Component({
  selector: 'app-main-layout',
  templateUrl: './main-layout.page.html',
  styleUrls: ['./main-layout.page.scss'],
  standalone: true,
  imports: [CommonModule, RouterModule, IonMenu, IonHeader, IonToolbar, IonTitle, IonContent, IonAvatar, IonIcon, IonList, IonMenuToggle, IonItem, IonLabel, IonListHeader, IonFooter, IonTabs, IonRouterOutlet, IonTabBar, IonTabButton],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MainLayoutPage implements OnInit, OnDestroy {
  private routerSub!: Subscription;
  private readonly router = inject(Router);
  private readonly menuCtrl = inject(MenuController);
  private readonly authStore = inject(AuthStore);
  private readonly profileStore = inject(ProfileStore);
  public readonly navState = inject(DashboardStore);

  private readonly BASE_URL: string = 'http://localhost:3000';
  public readonly Roles = UserRole;

  /** Signal computada del usuario actual (R5: Tipado Seguro) */
  public readonly user = this.authStore.user;

  /** Signal computada del modo de vista activo */
  public readonly currentMode = computed(() => this.navState.activeViewMode());

  /**
   * @constructor
   * @description Registra la librería de iconos necesaria para AviTour.
   */
  constructor() {
    addIcons({
      personOutline,
      journalOutline,
      mapOutline,
      peopleOutline,
      peopleCircleOutline,
      scanOutline,
      trophyOutline,
      businessOutline,
      checkboxOutline,
      swapHorizontalOutline,
      logOutOutline,
      homeOutline,
      cameraOutline,
      pawOutline,
      gridOutline,
      listOutline,
      searchOutline,
      binocularsOutline,
      navigateOutline,
    });
  }

  /**
   * @method ngOnInit
   * @description Inicializa suscripciones de navegación y sincronización proactiva (R2).
   */
  async ngOnInit(): Promise<void> {
    this.routerSub = this.router.events
      .pipe(
        filter(
          (event): event is NavigationEnd => event instanceof NavigationEnd
        )
      )
      .subscribe(() => {
        this.menuCtrl.close();
      });

    await this.syncUserProfile();
  }

  /**
   * @method syncUserProfile
   * @description Refresca los datos del usuario desde el servidor para evitar "datos stale" (R1).
   * @private
   */
  private async syncUserProfile(): Promise<void> {
    try {
      await this.profileStore.loadProfile();
    } catch (e) {
      console.warn('[MainLayout] Error en sincronización proactiva de perfil.');
    }
  }

  /**
   * @method ngOnDestroy
   * @description Limpieza de recursos para prevenir fugas de memoria.
   */
  ngOnDestroy(): void {
    if (this.routerSub) this.routerSub.unsubscribe();
  }

  /**
   * @method getImageUrl
   * @param {string | undefined | null} path - Ruta relativa o absoluta del recurso.
   * @returns {string} URL resuelta para el renderizado.
   */
  public getImageUrl(path: string | undefined | null): string {
    if (!path) {
      return 'https://ionicframework.com/docs/img/demos/avatar.svg';
    }
    return path.startsWith('http') ? path : `${this.BASE_URL}${path}`;
  }

  /**
   * @method handleImageError
   * @description Gestiona fallos de carga de imágenes sin usar 'any' (R5).
   * @param {Event} event - Evento nativo de error.
   */
  public handleImageError(event: Event): void {
    const element = event.target as HTMLImageElement;
    element.src = 'https://ionicframework.com/docs/img/demos/avatar.svg';
  }

  /**
   * @method logout
   * @description Cierra la sesión y limpia el estado global de navegación.
   */
  async logout(): Promise<void> {
    await this.menuCtrl.close();
    this.navState.setMode(null);
    await this.authStore.logout();
    this.router.navigate(['/auth/login'], { replaceUrl: true });
  }

  /**
   * @method setMode
   * @description Cambia el modo de visualización polimórfico (Pajarero/Proveedor).
   * @param {ViewMode} mode - Nuevo modo de vista.
   */
  async setMode(mode: ViewMode): Promise<void> {
    this.navState.setMode(mode);
    await this.menuCtrl.close();
  }
}

import { Component, inject, signal, computed } from '@angular/core';
