import { StatWidgetComponent } from './../../shared/components/stat-widget/stat-widget.component';
import { ChangePasswordComponent } from './components/change-password.component';
import {
  Component,
  inject,
  signal,
  ChangeDetectionStrategy,
  OnInit,
  computed,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute } from '@angular/router';
import { ModalController, IonContent, IonButton, IonIcon, IonSelect, IonSelectOption, IonList, IonItem, IonLabel, IonSpinner, IonHeader, IonToolbar, IonButtons, IonBackButton, IonTitle, IonModal } from '@ionic/angular';
import { Camera, CameraResultType, CameraSource } from '@capacitor/camera';

// Core Services, Stores & Models
import { ProfileStore } from '../../core/stores/profile.store';
import { UiService } from '../../core/services/ui.service';
import { AuthStore } from '../../core/stores/auth.store';
import { UserStats } from '../../core/models/auth.models';

// Icons
import { addIcons } from 'ionicons';
import {
  atOutline,
  cameraOutline,
  imageOutline,
  locationOutline,
  logoInstagram,
  bookOutline,
  trophyOutline,
  binocularsOutline,
  eyeOutline,
  pawOutline,
  mailOutline,
  lockClosedOutline,
  chevronForwardOutline,
  calendarOutline,
  timeOutline,
} from 'ionicons/icons';
import { AuthInputComponent } from '../../shared/components/auth-input/auth-input.component';
import { PasswordInputComponent } from '../../shared/components/password-input/password-input.component';
import { AuthCardHeaderComponent } from '../../shared/components/auth-card-header/auth-card-header.component';

import { LoadingComponent } from '../../shared/components/loading/loading.component';
import { UserMedalsComponent } from './components/user-medals/user-medals.component';

/**
 * @class ProfilePage
 * @description Gestión de perfil de usuario en AviTour.
 * Implementa geografía dependiente, validación de Instagram y modo visitante con Bio/Social.
 */
@Component({
  selector: 'app-profile',
  templateUrl: './profile.page.html',
  styleUrls: ['./profile.page.scss'],
  standalone: true,
  imports: [CommonModule, FormsModule, AuthInputComponent, PasswordInputComponent, AuthCardHeaderComponent, StatWidgetComponent, LoadingComponent, IonContent, IonButton, IonIcon, IonSelect, IonSelectOption, IonList, IonItem, IonLabel, IonSpinner, IonHeader, IonToolbar, IonButtons, IonBackButton, IonTitle, IonModal],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ProfilePage implements OnInit {
  private readonly profileStore = inject(ProfileStore);
  private readonly route = inject(ActivatedRoute);
  public readonly authStore = inject(AuthStore);
  private readonly ui = inject(UiService);
  private readonly modalCtrl = inject(ModalController);

  /** @description Datos del usuario en vista ligados al Store */
  public viewedUser = this.profileStore.viewedUser;
  /** @description Estado de carga del perfil */
  public isLoading = this.profileStore.isLoading;

  // Campos del formulario con signals
  public username = signal<string>('');
  public firstName = signal<string>('');
  public lastName = signal<string>('');
  public department = signal<string>('');
  public municipality = signal<string>('');
  public instagram = signal<string>('');
  public bio = signal<string>('');

  public isFormSubmitted = signal<boolean>(false);
  public isPristine = signal<boolean>(true);

  public isFirstNameValid = computed(() => this.firstName().length >= 2);
  public isLastNameValid = computed(() => this.lastName().length >= 2);
  public isInstagramValid = computed(() => {
    const val = this.instagram();
    if (!val) return true; // Optional
    return /^(https?:\/\/)?(www\.)?instagram\.com\/[a-zA-Z0-9._-]+\/?$/.test(val);
  });
  public isBioValid = computed(() => this.bio().length <= 500);

  public isFormValid = computed(() => 
    this.isFirstNameValid() && this.isLastNameValid() && this.isInstagramValid() && this.isBioValid()
  );

  /** @description Listado de departamentos */
  public departments = this.profileStore.departments;
  /** @description Listado de municipios del departamento seleccionado */
  public municipalities = this.profileStore.municipalities;

  /** @description URL base del backend para activos estáticos */
  private readonly BASE_URL = 'http://localhost:3000';

  /** @description Computado para determinar propiedad del perfil */
  public isOwnProfile = computed(() => {
    const viewed = this.viewedUser();
    const current = this.authStore.user();
    return viewed && current ? viewed.id == current.id : false;
  });

  /** @description Estadísticas de actividad */
  public stats = signal<UserStats>({
    speciesCount: 42,
    sightingsCount: 128,
    medalsCount: 5,
    daysInApp: 15,
    natureTimeMinutes: 120,
  });

  constructor() {
    addIcons({
      atOutline,
      cameraOutline,
      imageOutline,
      locationOutline,
      logoInstagram,
      bookOutline,
      trophyOutline,
      binocularsOutline,
      eyeOutline,
      pawOutline,
      mailOutline,
      lockClosedOutline,
      chevronForwardOutline,
      calendarOutline,
      timeOutline,
    });
  }

  /**
   * @method ngOnInit
   * @description Inicialización de vista y precarga de geografía.
   */
  async ngOnInit(): Promise<void> {
    this.initForm();
    await this.profileStore.loadDepartments();
    this.checkRouteAndLoad();
  }

  /**
   * @method getImageUrl
   * @description Resuelve la URL absoluta para recursos multimedia.
   * @param {string | undefined} path - Ruta relativa.
   */
  public getImageUrl(path: string | undefined): string {
    if (!path) return '';
    return path.startsWith('http') ? path : `${this.BASE_URL}${path}`;
  }

  /**
   * @method initForm
   * @description Configura validadores y estructura (Bio al final).
   */
  private initForm(): void {
    // Ya no se usa FormGroup, se usan Signals
  }

  // Marcar como dirty al cambiar
  onFieldChange() {
    this.isPristine.set(false);
  }

  /**
   * @method onDepartmentChange
   * Maneja la selección de departamento para cargar municipios.
   * @param {CustomEvent} event - Evento de cambio de IonSelect.
   */
  async onDepartmentChange(event: CustomEvent): Promise<void> {
    const name = event.detail.value;
    const dept = this.departments().find((d) => d.name === name);
    if (dept) {
      await this.profileStore.loadMunicipalities(dept.id);
      this.municipality.set('');
      this.onFieldChange();
    }
  }

  /**
   * @method checkRouteAndLoad
   * @description Determina el usuario a visualizar.
   */
  private async checkRouteAndLoad(): Promise<void> {
    const userId = this.route.snapshot.paramMap.get('id');
    try {
      const data = await this.profileStore.loadProfile(userId);
      if (data) {
        // Patch values to signals
        this.username.set(data.username || '');
        this.firstName.set(data.firstName || '');
        this.lastName.set(data.lastName || '');
        this.department.set(data.department || '');
        this.municipality.set(data.municipality || '');
        this.instagram.set(data.instagram || '');
        this.bio.set(data.bio || '');

        // Carga de municipios si existe departamento previo
        if (data.department) {
          const dept = this.departments().find(
            (d) => d.name === data.department
          );
          if (dept) {
            await this.profileStore.loadMunicipalities(dept.id);
          }
        }

        if (data.stats) {
          this.stats.set(data.stats);
        }
      }
    } catch (error) {
      console.error('Error loading profile', error);
    }
  }

  /**
   * @method onUpdateProfile
   * @description Persiste los cambios de texto en el backend.
   */
  async onUpdateProfile(): Promise<void> {
    this.isFormSubmitted.set(true);
    if (!this.isOwnProfile() || !this.isFormValid()) return;
    await this.ui.showLoading('Sincronizando...');
    try {
      const payload = {
        firstName: this.firstName(),
        lastName: this.lastName(),
        department: this.department(),
        municipality: this.municipality(),
        instagram: this.instagram(),
        bio: this.bio(),
      };
      await this.profileStore.updateProfile(payload);
      await this.ui.dismissLoading();
      this.ui.showToast('Perfil actualizado', 'success');
      this.isPristine.set(true);
      this.isFormSubmitted.set(false);
    } catch (error) {
      await this.ui.dismissLoading();
    }
  }

  /**
   * @method goToSecurity
   * @description Navegación o apertura de controles para cambio de contraseña.
   */
  async goToSecurity() {
    if (!this.isOwnProfile()) return;

    const modal = await this.modalCtrl.create({
      component: ChangePasswordComponent,
      breakpoints: [0, 0.6, 1], // R2: Diseño responsive (Bottom Sheet)
      initialBreakpoint: 1,
    });
    return await modal.present();
  }

  /**
   * @method changePhoto
   * @description Gestión multimedia desde galería.
   */
  async changePhoto(type: 'AVATAR' | 'COVER'): Promise<void> {
    if (!this.isOwnProfile()) return;
    try {
      const image = await Camera.getPhoto({
        quality: 90,
        source: CameraSource.Photos,
        resultType: CameraResultType.Uri,
        allowEditing: true,
      });
      if (image.webPath) {
        await this.ui.showLoading('Subiendo...');
        const response = await fetch(image.webPath);
        const blob = await response.blob();
        await this.profileStore.uploadImage(
          blob,
          type,
          image.format
        );
        await this.ui.dismissLoading();
      }
    } catch (e) {
      console.warn('Cancelado');
    }
  }

  /**
   * @method openMedals
   * @description Muestra el listado de medallas del usuario en un modal interactivo.
   */
  async openMedals() {
    const modal = await this.modalCtrl.create({
      component: UserMedalsComponent,
      breakpoints: [0, 0.5, 0.8, 1],
      initialBreakpoint: 0.8,
    });
    return await modal.present();
  }
}

/**
 * @file map-tracker.component.ts
 * @sdd Dumb component que renderiza el trazo Polyline y los pines de observación.
 */
import { Component, ChangeDetectionStrategy, ViewChild, ElementRef, AfterViewInit, OnDestroy, input, effect } from '@angular/core';
import { CommonModule } from '@angular/common';
import { IRouteSighting } from '../../../../../../../../shared/models/routes.interface';
import * as L from 'leaflet';

@Component({
  selector: 'app-map-tracker',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="map-placeholder">
       <div class="hud">
         <div class="metric">📍 {{ path().length || 0 }} Puntos</div>
         <div class="metric">🦅 {{ sightings().length || 0 }} Avistamientos</div>
       </div>
       <div class="map-canvas" #mapContainer></div>
    </div>
  `,
  styleUrls: ['./map-tracker.component.scss']
})
export class MapTrackerComponent implements AfterViewInit, OnDestroy {
  path = input<[number, number][]>([]);
  sightings = input<IRouteSighting[]>([]);

  @ViewChild('mapContainer', { static: false }) mapContainer!: ElementRef;
  private map!: L.Map;
  private polyline!: L.Polyline;
  private markerLayer = L.layerGroup();

  private userMarker!: L.Marker;
  private firstPanDone = false;

  ngAfterViewInit() {
    this.initMap();
  }

  constructor() {
    effect(() => {
      const currentPath = this.path();
      const currentSightings = this.sightings();

      if (this.map) {
        if (currentPath && currentPath.length > 0) {
          // leaflet uses [lat, lng], path is [lng, lat]
          const latLngs = currentPath.map(p => [p[1], p[0]] as [number, number]);
          const currentPos = latLngs[latLngs.length - 1];

          this.polyline.setLatLngs(latLngs);

          if (!this.firstPanDone) {
            this.map.setView(currentPos, 17);
            this.firstPanDone = true;
          } else {
            this.map.panTo(currentPos);
          }

          // Update User Marker
          if (!this.userMarker) {
            const userIcon = L.divIcon({
              className: 'user-pulse-icon',
              html: '<div class="pulse-dot"></div>',
              iconSize: [18, 18],
              iconAnchor: [9, 9]
            });
            this.userMarker = L.marker(currentPos, { icon: userIcon, zIndexOffset: 1000 }).addTo(this.map);
          } else {
            this.userMarker.setLatLng(currentPos);
          }
        }

        if (currentSightings) {
          this.markerLayer.clearLayers();

          const birdIcon = L.divIcon({
            className: 'bird-sighting-icon',
            html: '<div style="background-color: var(--ion-color-secondary, #4C6793); width: 14px; height: 14px; border-radius: 50%; border: 2px solid white; box-shadow: 0 0 4px rgba(0,0,0,0.5);"></div>',
            iconSize: [18, 18],
            iconAnchor: [9, 9]
          });

          currentSightings.forEach(s => {
            const dateObj = new Date(s.timestamp);
            const dateStr = dateObj.toLocaleDateString();
            const timeStr = dateObj.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
            const sRecord = s as unknown as { birdInfo?: Record<string, string>, bird_id: string };
            const scientificName = sRecord.birdInfo?.['scientific_name'] || `Ave ID: ${sRecord.bird_id}`;
            const englishName = sRecord.birdInfo?.['english_name'] || '';

            const popupHtml = `
              <div class="bird-popup">
                <strong class="bird-popup__title">${scientificName}</strong><br>
                ${englishName ? `<span class="bird-popup__subtitle">${englishName}</span><br>` : ''}
                <span class="bird-popup__meta">📅 ${dateStr} - 🕒 ${timeStr}</span><br>
                <span class="bird-popup__detail"><strong>Cantidad:</strong> ${s.quantity}</span>
                ${s.details ? `<br><span class="bird-popup__detail"><strong>Detalle:</strong> ${s.details}</span>` : ''}
              </div>
            `;
            const m = L.marker([s.lat, s.lng], { icon: birdIcon }).bindPopup(popupHtml);
            this.markerLayer.addLayer(m);
          });
        }
      }
    });
  }

  private initMap() {
    this.map = L.map(this.mapContainer.nativeElement).setView([4.5709, -74.2973], 5);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '© OpenStreetMap AviTour'
    }).addTo(this.map);

    this.polyline = L.polyline([], { color: 'blue', weight: 4 }).addTo(this.map);
    this.markerLayer.addTo(this.map);

    // Ionic layout delay fix: ensure leaflet recalculates dimensions
    setTimeout(() => {
      this.map.invalidateSize();
    }, 400);
  }

  ngOnDestroy() {
    if (this.map) {
      this.map.remove();
    }
  }
}

/**
 * @file sighting-logger.component.ts
 * @sdd Dumb component que representa el panel inferior para registro veloz.
