import { Component, input, output, signal, ChangeDetectionStrategy, inject, ViewChild, computed } from '@angular/core';
import { IBirdSearch } from '../../../../../core/models/birds.interfaces';
import { IRouteSighting } from '../../../../../../../../shared/models/routes.interface';
import { CommonModule } from '@angular/common';
import { IonSearchbar, IonButton, IonIcon, IonList, IonItem, IonLabel, IonAvatar, IonInput, AlertController } from '@ionic/angular';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-sighting-logger',
  standalone: true,
  imports: [CommonModule, IonSearchbar, IonButton, IonIcon, IonList, IonItem, IonLabel, IonAvatar, IonInput, FormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './sighting-logger.component.html',
  styleUrls: ['./sighting-logger.component.scss']
})
export class SightingLoggerComponent {
  alertCtrl = inject(AlertController);

  searchResults = input<IBirdSearch[]>([]);
  sightingsLog = input<(IRouteSighting & { birdInfo?: Partial<IBirdSearch> })[]>([]);

  /** Evento emitido al buscar texto */
  search = output<string>();
  /** Evento emitido al agregar avistamiento */
  sightingAdded = output<{ birdId: string; quantity: number; details: string; birdInfo?: Partial<IBirdSearch> }>();

  @ViewChild(IonSearchbar, { static: false }) searchbar!: IonSearchbar;

  uniqueSpeciesCount = computed(() => this.sightingsLog().length);
  totalBirdsCount = computed(() => {
    return this.sightingsLog().reduce((acc: number, curr: any /* using any internally to skip reduce type hell */) => acc + ((curr['quantity'] as number) || 1), 0);
  });

  onSearchInput(event: CustomEvent) {
    const query = (event.target as HTMLInputElement).value?.toLowerCase() || '';
    this.search.emit(query);
  }

  async selectBird(bird: IBirdSearch) {
    const alert = await this.alertCtrl.create({
      header: 'Registrar Avistamiento',
      subHeader: bird['scientific_name'] as string,
      inputs: [
        { name: 'quantity', type: 'number', placeholder: 'Cantidad (Ej: 1)', min: 1, value: 1 },
        { name: 'details', type: 'text', placeholder: 'Detalles (ej: Comiendo frutas)' }
      ],
      buttons: [
        { text: 'Cancelar', role: 'cancel' },
        { 
          text: 'Guardar', 
          handler: (data: { quantity: string, details: string }) => {
            this.sightingAdded.emit({ 
              birdId: String(bird['id']), 
              quantity: parseInt(data.quantity, 10) || 1,
              details: data.details || '',
              birdInfo: bird
            });
            if (this.searchbar) {
              this.searchbar.value = '';
            }
          } 
        }
      ]
    });
    await alert.present();
  }
}

/**
 * @file route-workspace.page.ts
 * @sdd Smart Component contenedor. Configura el layout dividido y orquesta la conexión con ActiveRouteStore.
