/**
 * @file routes-landing.page.ts
 * @sdd Vista previa de rutas. Permite iniciar una ruta nueva, ver borradores y rutas enviadas.
 * [I/O]: Si hay conexión a internet, obtiene las rutas de Postgres, sino desde SQLite.
 */
export interface RouteModel {
  id: string;
  name?: string;
  start_time: string;
  end_time?: string;
  route_type: string;
  status: string;
  total_km?: number;
}

@Component({
  selector: 'app-routes-landing',
  standalone: true,
  imports: [CommonModule, FormsModule, IonHeader, IonToolbar, IonTitle, IonContent, IonButtons, IonMenuButton, IonFab, IonFabButton, IonIcon, IonList, IonItem, IonLabel, IonBadge, IonSegment, IonSegmentButton, IonCard, IonCardHeader, IonCardTitle, IonCardContent, IonButton, IonChip],
  templateUrl: './routes-landing.page.html',
  styleUrls: ['./routes-landing.page.scss']
})
export class RoutesLandingPage implements OnInit {
  router = inject(Router);
  db = inject(DbHelperService);
  network = inject(NetworkService);
  http = inject(HttpClient);

  currentTab = 'drafts';
  draftRoutes: RouteModel[] = [];
  sentRoutes: RouteModel[] = [];

  constructor() {
    addIcons({ add, timeOutline, checkmarkDoneOutline, mapOutline, globeOutline, cloudOfflineOutline });
  }

  /** Inicializa la página y carga las rutas */
  async ngOnInit() {
    await this.loadRoutes();
  }

  /** Refresca las rutas cada vez que la vista se hace activa */
  async ionViewWillEnter() {
    await this.loadRoutes();
  }

  /** Carga todas las rutas desde Postgres si hay red, sino desde SQLite */
  async loadRoutes() {
    try {
      let allRoutes: RouteModel[] = [];

      if (this.network.isOnline()) {
        try {
          console.log('[RoutesLanding] Online mode: fetching from Postgres');
          const remoteRoutes = await firstValueFrom(this.http.get<RouteModel[]>(`${environment.apiUrl}/v1/routes`));
          allRoutes = remoteRoutes || [];
        } catch(apiErr) {
          console.error('Error fetching routes from API, falling back to SQLite', apiErr);
          allRoutes = (await this.db.query('SELECT * FROM routes ORDER BY start_time DESC') || []) as unknown as RouteModel[];
        }
      } else {
        console.log('[RoutesLanding] Offline mode: fetching from SQLite');
        allRoutes = (await this.db.query('SELECT * FROM routes ORDER BY start_time DESC') || []) as unknown as RouteModel[];
      }

      this.draftRoutes = allRoutes.filter(r => r.status === 'DRAFT' || !r.status);
      this.sentRoutes = allRoutes.filter(r => r.status === 'COMPLETED');
    } catch(e: unknown) {
      console.error('Error cargando rutas:', e);
    }
  }

  /**
   * Navega a la vista para crear una nueva ruta.
   */
  startNewRoute() {
    this.router.navigate(['/home/route-workspace']);
  }

  /**
   * Navega a la vista de espacio de trabajo para continuar una ruta existente.
   * @param routeId ID de la ruta en borrador.
   */
  resumeRoute(routeId: string) {
    this.router.navigate(['/home/route-workspace'], { queryParams: { id: routeId } });
  }

  /**
   * Navega a la vista de espacio de trabajo en modo solo lectura.
   * @param routeId ID de la ruta enviada.
   */
  viewRoute(routeId: string) {
    this.router.navigate(['/home/route-workspace'], { queryParams: { id: routeId, readonly: true } });
  }

  /**
   * Calcula la duración en horas y minutos dado un inicio y un fin.
   * @param start Fecha de inicio ISO.
   * @param end Fecha de fin ISO.
   * @returns String formateado de la duración.
   */
  getDuration(start: string, end: string): string {
    if (!start || !end) return '';
    const diffMs = new Date(end).getTime() - new Date(start).getTime();
    if (diffMs < 0 || isNaN(diffMs)) return '';
    const diffMins = Math.floor(diffMs / 60000);
    const hrs = Math.floor(diffMins / 60);
    const mins = diffMins % 60;
    if (hrs > 0) return `${hrs}h ${mins}m`;
    return `${mins}m`;
  }
}

