 * @description Shared domain contracts for Guides and Sites (Offline-first Catalogs).
 * @io Used by both NestJS API (DTOs/Responses) and Angular SignalStores.
 * @edge_cases Coordinates mapped to lat/lng instead of PostGIS Point object for Frontend compatibility.
 */

export interface IGuide {
  id: string;
  fullName: string;
  location: string;
  specialty: string;
  rating: number;
  photoUrl: string;
  details: string;
  languages?: string;
  bio?: string;
  phone?: string;
  last_modified?: number;
  sql_deleted?: boolean;
}

export interface ISite {
  id: string;
  name: string;
  department: string;
  rating: number;
  description: string;
  photoUrl?: string;
  location: { lat: number; lng: number }; // Transformed from PostGIS
  routeGeoJson: unknown;
  services: string[];
  prices: Record<string, string>;
  expectedBirds?: string[];
  last_modified?: number;
  sql_deleted?: boolean;
}

export interface IBirdCatalog {
  id: number;
  scientific_name: string;
  english_name: string;
  common_name: string;
  min_altitude: number;
  max_altitude: number;
  viewing_difficulty: number;
  size?: number;
  environment?: string;
  behavior?: string;
  colors?: string;
  authority?: string;
  gbif_link?: string;
  wikiaves_link?: string;
  ebird_link?: string;
  other_sources?: string;
  base_image: string;
  image_copyright?: string;
  habitat_id: number;
  conservation_status_id: number;
  family_id: number;
  residency_type_id: number;
  feeding_type_id: number;
  beak_morphology_id: number;
  wing_morphology_id: number;
  tail_morphology_id: number;
  leg_morphology_id: number;
  additional_info_id: number;
  last_modified: string;
  sql_deleted: boolean;
}

export interface ISyncCatalogsResponse {
  guides: IGuide[];
  sites: ISite[];
  site_birds: { site_id: string; bird_id: string }[];
  timestamp: number;
  departments?: { id: number; name: string; sql_deleted?: boolean }[];
  municipalities?: { id: number; department_id: number; name: string; sql_deleted?: boolean }[];
  birds?: IBirdCatalog[];
}

/**
 * @sdd
 * - [Objetivo]: Contrato compartido para publicaciones del Feed Global.
 * - [I/O]: Usado por el cliente Angular y la API NestJS para la transferencia de datos y tipado.
 * - [Edge Cases]: La propiedad location puede ser nula si el usuario denegó los permisos de GPS.
 */
export interface FeedPost {
  id: string;
  authorId: string;
  authorName: string;
  authorAvatarUrl?: string;
  title: string;
  description: string;
  imageUrl: string;
  location: { lat: number; lng: number } | null;
  createdAt: string; // ISO 8601 string para cursor pagination
  repliesCount: number;
  savesCount: number;
  needsIdentification?: boolean;
}

export interface FeedReply {
  id: string;
  postId: string;
  authorId: string;
  authorName: string;
  authorAvatarUrl?: string;
  content: string;
  createdAt: string;
}

export interface FeedFavorite {
  userId: string;
  postId: string;
}

/**
 * @sdd
 * @description Shared domain contracts for GPS Tracking and Routes (Module 3).
 * @io Used by both NestJS API (DTOs/Responses) and Angular SignalStores/SQLite.
 * @edge_cases DTO arrays used for bulk synchronization when the device recovers network.
 */

export interface IRouteSighting {
  id: string;
  route_id: string;
  bird_id: string;
  lat: number;
  lng: number;
  timestamp: string;
  quantity: number;
  details?: string;
  sync_status?: 'pending_sync' | 'synced';
}

export interface IRoute {
  id: string;
  start_time: string;
  end_time?: string;
  route_type: 'estacionaria' | 'desplazamiento';
  total_km: number;
  duration_mins: number;
  path_geojson: string; // LineString geojson representations
  sync_status?: 'pending_sync' | 'synced';
  sightings?: IRouteSighting[]; // Nested sightings for Bulk Payload
  department_id?: number;
  municipality_id?: number;
}

export interface IUserSyncPayload {
  id: string;
  [key: string]: unknown;
}

export interface ISyncRoutesBulkPayload {
  routes: IRoute[];
  users?: IUserSyncPayload[];
}
